vec2 lp  = acLayerNorm;
vec4 src = fetchL(lp);

float a  = max(src.a, 1e-4);
vec3 sc  = src.rgb / a;
float l  = lum(sc);

float asp = acLayerSize.x / max(acLayerSize.y, 1.0);
vec2  c0  = centre - vec2(0.5);
c0.x *= asp;
vec2  q   = lp - vec2(0.5);
q.x *= asp;
q -= c0;

