float w = 1.0 - smoothstep(tol, tol + max(soft, 0.01), d);
vec3  t = rep;
if (hueOnly > 0.5){
// Keep the source luminance and take only the replacement's hue: recolour
// without flattening the shading underneath.
t = rep * (lum(c) / max(lum(rep), 1e-4));
}
return mix(c, t, w);
}

void main(){
vec2 lp  = acLayerNorm;
vec4 src = fetchL(lp);

float a  = max(src.a, 1e-4);
vec3 sc  = src.rgb / a;

vec3 c = sc;
c = applySlot(c, findCol1.rgb, repCol1.rgb, tol1, soft1, hueOnly1);
c = applySlot(c, findCol2.rgb, repCol2.rgb, tol2, soft2, hueOnly2);
c = applySlot(c, findCol3.rgb, repCol3.rgb, tol3, soft3, hueOnly3);

float l = lum(c);
c = sat3v(mix(vec3(l), c, satBoost));
c = sat3v(mix(sc, c, replaceMix));

vec3  col = mix(sc, c, mixAmt);
float oA  = src.a * opacity;
gl_FragColor = vec4(col * oA, oA);
}

vec3 sat3v(vec3 c){ return clamp(c, vec3(0.0), vec3(1.0)); }

// LAYER -> SCREEN. The bend is computed from layer coordinates and every read
// goes back through the layer transform.
// Positions are anchored on acScreenNorm - the engine's own screen position for
// this fragment - so the anchor never depends on the matrix. Only the DELTA goes
// through acLayerToScreen, and the w=0 multiply cancels the translation, so a
// layer-space offset becomes a screen-space offset exactly. fetchL(acLayerNorm)
// therefore returns texture2DCv(inputImg.texture, acScreenNorm), the engine idiom.
vec2 lpToScreen(vec2 v){ return acScreenNorm + (vec4(v - acLayerNorm, 0.0, 0.0) * acLayerToScreen).xy; }
vec4 fetchL(vec2 lp){ return texture2DCv(inputImg.texture, clamp(lpToScreen(lp), 0.0, 1.0)); }

vec2 rot2(vec2 p, float a){ float c = cos(a); float s = sin(a); return vec2(p.x * c - p.y * s, p.x * s + p.y * c); }

vec2 edgeFix(vec2 lp){
if (edgeMode <= 0) return clamp(lp, 0.0, 1.0);
if (edgeMode <= 1){
vec2 m = mod(lp, vec2(2.0, 2.0));
return abs(m - vec2(1.0, 1.0)) * -1.0 + vec2(1.0);
}
return fract(lp);
}

void main(){
vec2 lp  = acLayerNorm;
vec4 src = fetchL(lp);

float al = max(src.a, 1.0e-4);
vec3 sc = src.rgb / al;

float asp = acLayerSize.x / max(acLayerSize.y, 1.0);
vec2  q   = vec2((lp.x - 0.5) * asp, lp.y - 0.5);

// ---- pick the bend axis -------------------------------------------------
// u runs -1..1 along the bending axis, v is the perpendicular coordinate.
float u;
float v;
if (bendAxis <= 0){
u = (lp.x - anchor) * 2.0;
v = lp.y;
} else if (bendAxis <= 1){
u = (lp.y - anchor) * 2.0;
v = lp.x;
} else {
// Radial: bend outward from the centre, so u is the radius.
u = length(q) * 2.0;
v = atan(q.y, q.x) / 6.2831853 + 0.5;
}

// ---- half angle ---------------------------------------------------------
// S-Curve flips the sign of the bend across the perpendicular axis. A smooth
// flip rather than sign() so the reversal has no crease in it.
float th = bend * 2.60;
if (curveMode >= 4 && curveMode <= 4){
th *= mix(-1.0, 1.0, smoothstep(0.0, 1.0, clamp(v, 0.0, 1.0)));
}

// ---- cylindrical mapping ------------------------------------------------
// R * sin(a) with R = 1/th keeps this an identity as th -> 0, so bend 0 is a
// true no-op rather than a near-miss.
float a    = u * th;
float R    = 1.0 / max(abs(th), 1.0e-4);
float X    = R * sin(a);
float Z    = R * (cos(a) - 1.0);
float pAmt = perspective;
if (curveMode <= 1) pAmt *= 0.85;
if (curveMode >= 2 && curveMode <= 2) pAmt *= 0.25;
if (curveMode >= 5) pAmt = max(pAmt, 0.70);
float persp = 1.0 / max(1.0 + Z * pAmt * 1.7, 0.06);

// Profile blends between a flat linear map and the full arc, so the same bend
// amount can be a gentle roll or a tight tube.
float nu = mix(u, X * persp, clamp(profile, 0.0, 1.0));

// ---- rebuild the sample coordinate -------------------------------------
float su;
float sv;
if (bendAxis <= 0){
su = anchor + nu * 0.5;
sv = (v - 0.5) * persp + 0.5;
} else if (bendAxis <= 1){
sv = anchor + nu * 0.5;
su = (v - 0.5) * persp + 0.5;
} else {
// Radial bend: keep the angle, bend the radius.
float rad = clamp(nu * 0.5, 0.0, 1.4);
su = 0.5 + cos(v * 6.2831853) * rad / max(asp, 1.0e-3);
sv = 0.5 + sin(v * 6.2831853) * rad;
}

vec2 sp = vec2(su, sv);

// ---- twist --------------------------------------------------------------
if (abs(twist) > 0.001){
sp = vec2(0.5) + rot2(sp - vec2(0.5), twist * nu * 0.85);
}

vec4 got = texture2DCv(inputImg.texture, clamp(lpToScreen(edgeFix(sp)), 0.0, 1.0));
float ga = max(got.a, 1.0e-4);
vec3 gc  = got.rgb / ga;

// ---- shading ------------------------------------------------------------
// The surface tangent is (dX, dZ) = (cos a, -sin a); rotating it 90 degrees in
// the x-z plane gives the normal, which is what the light is dotted against.
float sh = 1.0;
if (shading > 0.001 || sheen > 0.001){
vec2  nrm = normalize(vec2(sin(a), cos(a)) + vec2(1.0e-5));
float la  = radians(lightAngle);
vec3  L   = normalize(vec3(cos(la), 0.0, sin(la)));
vec3  N   = normalize(vec3(nrm.x, 0.0, nrm.y));
float dp  = clamp(dot(N, L), 0.0, 1.0);
sh = mix(1.0, 0.42 + 1.00 * dp, clamp(shading, 0.0, 1.0));
gc *= sh;
if (sheen > 0.001){
// A tight specular band that travels along the crest of the curve.
float sp2 = pow(dp, 9.0) * sheen * 0.65;
gc += vec3(sp2);
}
}

vec3  col = mix(sc, gc, mixAmt);
float oA  = got.a * opacity;
gl_FragColor = vec4(col * oA, oA);
}

const vec3 gmLuma = vec3(0.2126, 0.7152, 0.0722);
float gmHash21(vec2 p) {
return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}
float gmNoise(vec2 p) {
vec2 i = floor(p);
vec2 f = fract(p);
vec2 u = f * f * (3.0 - 2.0 * f);
return mix(mix(gmHash21(i), gmHash21(i + vec2(1.0, 0.0)), u.x),
mix(gmHash21(i + vec2(0.0, 1.0)), gmHash21(i + vec2(1.0, 1.0)), u.x), u.y);
}
float gmPotential(vec2 p, float t) {
mat2 turn = mat2(0.8, -0.6, 0.6, 0.8);
p = p * scale + seed * vec2(1.71, 2.43);
float n0 = gmNoise(p + vec2(t * 0.11, -t * 0.07));
p = turn * p * 2.03 + vec2(4.7, 8.2);
float n1 = gmNoise(p - vec2(t * 0.09, t * 0.13));
p = turn * p * 2.01 + vec2(9.1, 3.4);
float n2 = gmNoise(p + vec2(t * 0.17, t * 0.05));
float detailed = n0 * 0.5714286 + n1 * 0.2857143 + n2 * 0.1428571;
return mix(detailed, n0, viscosity);
}
vec2 gmVelocity(vec2 p, float t) {
const float e = 0.015;
float leftValue = gmPotential(p - vec2(e, 0.0), t);
float rightValue = gmPotential(p + vec2(e, 0.0), t);
float downValue = gmPotential(p - vec2(0.0, e), t);
float upValue = gmPotential(p + vec2(0.0, e), t);
vec2 gradient = vec2(rightValue - leftValue, upValue - downValue) / (2.0 * e);
return vec2(gradient.y, -gradient.x) * vorticity;
}
void main() {
vec2 uv = acScreenNorm;
vec2 texSize = max(inputImg.size, vec2(1.0));
float aspect = texSize.x / texSize.y;
vec2 p = (uv - 0.5) * vec2(aspect, 1.0);
float t = evolution + (autoAnimate ? acTime * speed : 0.0);
float dt = strength * 0.035;
vec2 velocityA = gmVelocity(p, t);
vec2 midpoint = p - velocityA * dt * 0.5;
vec2 velocityB = gmVelocity(midpoint, t);
vec2 advectedPoint = p - velocityB * dt;
vec2 advectedUv = uv + (advectedPoint - p) / vec2(aspect, 1.0);
advectedUv = 1.0 - abs(mod(advectedUv, 2.0) - 1.0);
vec4 src = texture2DCv(inputImg.texture, uv);
vec4 moved = texture2DCv(inputImg.texture, advectedUv);
float flowValue = gmPotential(advectedPoint, t);
float tone = dot(moved.rgb, gmLuma);
float inkMask = clamp((tone - 0.5) * inkContrast + 0.5 + (flowValue - 0.5) * 0.35, 0.0, 1.0);
vec3 inkColor = mix(inkColorA.rgb, inkColorB.rgb, smoothstep(0.0, 1.0, inkMask));
vec3 colored = mix(moved.rgb, inkColor * max(moved.a, 0.0001), inkAmount);
vec4 result = vec4(colored, moved.a);
gl_FragColor = mix(src, result, clamp(mixAmount, 0.0, 1.0));
}

#define GM_SAFE_EPSILON 0.0001
float gmSafeDivide(float numerator, float denominator){
float safeDenominator = max(abs(denominator), 0.01);
return numerator / safeDenominator;
}
mat3 gmRotateX(float angle){
float s = sin(angle);
float c = cos(angle);
return mat3(1.0, 0.0, 0.0, 0.0, c, s, 0.0, -s, c);
}
mat3 gmRotateY(float angle){
float s = sin(angle);
float c = cos(angle);
return mat3(c, 0.0, -s, 0.0, 1.0, 0.0, s, 0.0, c);
}
mat3 gmRotateZ(float angle){
float s = sin(angle);
float c = cos(angle);
return mat3(c, s, 0.0, -s, c, 0.0, 0.0, 0.0, 1.0);
}
float gmFountainField(vec2 screen, float timeValue, int stepBudget, int octaveBudget){
vec3 ray = vec3(screen, focalLength);
ray = gmRotateZ(cameraRoll) * gmRotateX(cameraPitch) * gmRotateY(cameraYaw) * ray;
vec3 queryPosition = vec3(cameraX, cameraY, cameraZ);
vec3 position = vec3(0.0);
float stepValue = 0.0;
float radius = 0.0;
float energy = 0.0;
float normalization = max(float(stepBudget) - 0.9, 1.0);
float intensityFrequency = frequencyBase * pow(frequencyGrowth, 6.0);
for(int i = 0; i < 95; i++){
if(i >= stepBudget) break;
float guardedStep = clamp(stepValue, -2.0, 2.0);
queryPosition += ray * guardedStep * radius * stepLength;
queryPosition = clamp(queryPosition, vec3(-10000.0), vec3(10000.0));
position = queryPosition;
radius = length(position) + max(radiusBias, 1.0);
float normalizedDepth = gmSafeDivide(position.z, radius);
position = vec3(
log(max(radius, GM_SAFE_EPSILON)) - timeValue * depthFlow,
exp(-clamp(normalizedDepth, -0.1, 1.4)) + heightOffset,
atan(position.y, position.x) + timeValue * orbitFlow
);
position.y -= surfaceLevel;
stepValue = position.y;
float frequency = frequencyBase;
for(int octave = 0; octave < 6; octave++){
if(octave >= octaveBudget) break;
vec3 waveA = sin(position.zxx * frequency);
vec3 waveB = vec3(1.0) - cos(position.yyz * frequency);
stepValue += gmSafeDivide(dot(waveA, waveB), frequency) * turbulence;
frequency *= frequencyGrowth;
}
energy += clamp(stepValue * intensityFrequency, 0.0, 1.0) / normalization;
}
return clamp(energy, 0.0, 1.5);
}
void main(){
vec2 uv = acScreenNorm;
vec4 source = texture2DCv(inputImg.texture, uv);
float timeValue = evolution;
if(autoAnimate) timeValue += acTime * speed;
vec2 center = vec2(0.5 + centerX * 0.5, 0.5 + centerY * 0.5);
vec2 screen = uv - center;
screen.x *= acScreenSize.x / max(acScreenSize.y, 1.0);
screen *= zoom;
int stepBudget = 48;
int octaveBudget = 4;
if(quality == 1){
stepBudget = 70;
octaveBudget = 5;
}else if(quality == 2){
stepBudget = 95;
octaveBudget = 6;
}
float field = gmFountainField(screen, timeValue, stepBudget, octaveBudget);
field = pow(max(field * intensity, 0.0), contrast);
field = clamp(field, 0.0, 1.0);
vec3 generated = mix(lowColor.rgb, highColor.rgb, field);
float coreMask = smoothstep(0.55, 1.0, field) * hotCore;
generated = mix(generated, hotColor.rgb, coreMask);
if(invert) generated = vec3(1.0) - generated;
vec3 effected = generated;
if(blendMode == 1){
effected = clamp(source.rgb + generated, 0.0, 1.0);
}else if(blendMode == 2){
effected = vec3(1.0) - (vec3(1.0) - source.rgb) * (vec3(1.0) - generated);
}
vec3 outputColor = mix(source.rgb, effected, mixAmount);
float outputAlpha = clipToLayer ? source.a : 1.0;
gl_FragColor = vec4(outputColor * outputAlpha, outputAlpha);
}

vec4 gmSample(sampler2D tex, vec2 uv) {
return texture2DCv(tex, uv);
}
vec4 gmBox4(sampler2D tex, vec2 uv, vec2 texel,
vec2 a, vec2 b, vec2 c, vec2 d) {
return gmSample(tex, uv + a * texel) +
gmSample(tex, uv + b * texel) +
gmSample(tex, uv + c * texel) +
gmSample(tex, uv + d * texel);
}
vec4 gmNodeDownsample(sampler2D tex, vec2 uv, vec2 texel) {
const float W1 = 0.0208333004;
const float W2 = 0.0833332986;
const float W3 = 0.00923329964;
vec4 result = vec4(0.0);
result += gmBox4(tex, uv, texel,
vec2(-0.9, 0.0), vec2(0.0, 0.0),
vec2(0.0, 0.9), vec2(-0.9, 0.9)) * W1;
result += gmBox4(tex, uv, texel,
vec2(-0.45, 0.45), vec2(0.45, 0.45),
vec2(-0.45, -0.45), vec2(0.45, -0.45)) * W2;
result += gmBox4(tex, uv, texel,
vec2(0.0, 0.0), vec2(0.9, 0.9),
vec2(0.0, 0.9), vec2(0.9, 0.0)) * W1;
result += gmBox4(tex, uv, texel,
vec2(0.0, -0.9), vec2(-0.9, -0.9),
vec2(-0.9, 0.0), vec2(0.0, 0.0)) * W1;
result += gmBox4(tex, uv, texel,
vec2(0.0, -0.9), vec2(0.9, -0.9),
vec2(0.0, 0.0), vec2(0.9, 0.0)) * W1;
result += gmBox4(tex, uv, texel,
vec2(-1.45, 1.45), vec2(-0.45, 1.45),
vec2(-1.45, 0.45), vec2(-0.45, 0.45)) * W3;
result += gmBox4(tex, uv, texel,
vec2(-0.45, 1.45), vec2(0.45, 1.45),
vec2(-0.45, 0.45), vec2(0.45, 0.45)) * W3;
result += gmBox4(tex, uv, texel,
vec2(1.45, 0.45), vec2(0.45, 0.45),
vec2(0.45, 1.45), vec2(1.45, 1.45)) * W3;
result += gmBox4(tex, uv, texel,
vec2(-1.45, 0.45), vec2(-0.45, 0.45),
vec2(-1.45, -0.45), vec2(-0.45, -0.45)) * W3;
result += gmBox4(tex, uv, texel,
vec2(-0.45, 0.45), vec2(0.45, 0.45),
vec2(-0.45, -0.45), vec2(0.45, -0.45)) * W3;
result += gmBox4(tex, uv, texel,
vec2(1.45, 0.45), vec2(0.45, 0.45),
vec2(0.45, -0.45), vec2(1.45, -0.45)) * W3;
result += gmBox4(tex, uv, texel,
vec2(-1.45, -1.45), vec2(-0.45, -1.45),
vec2(-1.45, -0.45), vec2(-0.45, -0.45)) * W3;
result += gmBox4(tex, uv, texel,
vec2(-0.45, -1.45), vec2(0.45, -1.45),
vec2(-0.45, -0.45), vec2(0.45, -0.45)) * W3;
result += gmBox4(tex, uv, texel,
vec2(0.45, -1.45), vec2(1.45, -1.45),
vec2(0.45, -0.45), vec2(1.45, -0.45)) * W3;
return result;
}
vec4 gmNodeUpsample(sampler2D tex, vec2 uv, vec2 texel) {
vec4 result = gmSample(tex, uv) * 0.159999996;
result += (gmSample(tex, uv + vec2( 1.0,  0.0) * texel) +
gmSample(tex, uv + vec2(-1.0,  0.0) * texel) +
gmSample(tex, uv + vec2( 0.0,  1.0) * texel) +
gmSample(tex, uv + vec2( 0.0, -1.0) * texel)) * 0.0799999982;
result += (gmSample(tex, uv + vec2( 1.0,  1.0) * texel) +
gmSample(tex, uv + vec2(-1.0,  1.0) * texel) +
gmSample(tex, uv + vec2( 1.0, -1.0) * texel) +
gmSample(tex, uv + vec2(-1.0, -1.0) * texel) +
gmSample(tex, uv + vec2( 2.0,  0.0) * texel) +
gmSample(tex, uv + vec2(-2.0,  0.0) * texel) +
gmSample(tex, uv + vec2( 0.0,  2.0) * texel) +
gmSample(tex, uv + vec2( 0.0, -2.0) * texel)) * 0.0399999991;
result += (gmSample(tex, uv + vec2(-2.0,  1.0) * texel) +
gmSample(tex, uv + vec2(-1.0,  2.0) * texel) +
gmSample(tex, uv + vec2( 1.0,  2.0) * texel) +
gmSample(tex, uv + vec2( 2.0,  1.0) * texel) +
gmSample(tex, uv + vec2( 2.0, -1.0) * texel) +
gmSample(tex, uv + vec2( 1.0, -2.0) * texel) +
gmSample(tex, uv + vec2(-1.0, -2.0) * texel) +
gmSample(tex, uv + vec2(-2.0, -1.0) * texel)) * 0.0199999996;
result += (gmSample(tex, uv + vec2(-2.0,  2.0) * texel) +
gmSample(tex, uv + vec2( 2.0,  2.0) * texel) +
gmSample(tex, uv + vec2( 2.0, -2.0) * texel) +
gmSample(tex, uv + vec2(-2.0, -2.0) * texel)) * 0.00999999978;
return result;
}
vec2 gmTexel(vec2 encodedSize) {
return 1.0 / max(encodedSize, vec2(1.0));
}
vec4 gmExtract(vec4 filtered) {
float energy2 = dot(filtered.rgb, filtered.rgb);
vec3 direction = filtered.rgb * inversesqrt(max(energy2, 1.0e-20));
vec3 limited = min(direction * thresholdHigh,
max(filtered.rgb, vec3(0.0))) * 0.908999979;
float peak = max(max(limited.r, limited.g), limited.b);
float above = peak - thresholdLow;
float safePeak = max(peak, 9.99999975e-05);
float knee = clamp(above + 9.99999975e-05,
0.0, 0.000199999995);
knee = knee * knee * 2000.00012;
float contribution = max(above, knee);
filtered.rgb = max(limited * contribution / safePeak, vec3(0.0));
return filtered * glowColor;
}
void main() {
vec2 uv = acScreenNorm;
float scattering = clamp(bloomScattering, 1.0, 10.0);
float spread = mix(0.75, 6.5, (scattering - 1.0) / 9.0);
if (acPass == 0) {
gl_FragColor = gmExtract(gmNodeDownsample(
inputImg.texture, uv, gmTexel(inputImg.size)));
return;
}
if (acPass == 1) {
gl_FragColor = gmNodeDownsample(
down0.texture, uv, gmTexel(down0.size));
return;
}
if (acPass == 2) {
gl_FragColor = gmNodeDownsample(
down1.texture, uv, gmTexel(down1.size));
return;
}
if (acPass == 3) {
gl_FragColor = gmNodeDownsample(
down2.texture, uv, gmTexel(down2.size));
return;
}
if (acPass == 4) {
gl_FragColor = gmNodeUpsample(
down2.texture, uv, gmTexel(down2.size) * spread) +
gmSample(down3.texture, uv);
return;
}
if (acPass == 5) {
gl_FragColor = gmNodeUpsample(
down1.texture, uv, gmTexel(down1.size) * spread) +
gmSample(up2.texture, uv);
return;
}
if (acPass == 6) {
gl_FragColor = gmNodeUpsample(
down0.texture, uv, gmTexel(down0.size) * spread) +
gmSample(up1.texture, uv);
return;
}
vec4 source = gmSample(inputImg.texture, uv);
vec4 bloom = gmNodeUpsample(
up0.texture, uv, gmTexel(up0.size) * spread);
vec4 result = source + bloom * bloomIntensity;
if (preserveAlpha) result.a = source.a;
gl_FragColor = result;
}

#define PI 3.14159265359
void main() {
vec2 uv = acScreenNorm;
vec4 texColor = texture2DCv(inputImg.texture, uv);
float baseAlpha = texColor.a;
vec2 st = (uv - 0.5) - vec2(position.x, -position.y) * 0.5;
st.x *= acScreenSize.x / max(acScreenSize.y, 1.0);
st /= max(scale, 0.001);
float rad = length(st);
float angle = atan(st.y, st.x);
float r = max(rad, 0.001);
float u = depth / r + acTime * speed;
float v = angle / PI + r * twist;
float ringDist = abs(fract(u * rings) - 0.5);
float line = smoothstep(thickness, thickness * 0.5, ringDist);
float wave = sin(v * PI * 4.0 + acTime) * 0.1;
float distortedRingDist = abs(fract(u * rings + wave) - 0.5);
float glow = exp(-distortedRingDist * 10.0) * glowIntensity;
float colorMix = sin(u * 2.0) * 0.5 + 0.5;
vec3 ringColor = mix(color1.rgb, color2.rgb, colorMix);
vec3 finalColor = ringColor * (line + glow);
float centerFade = smoothstep(0.0, 0.2, r);
finalColor *= centerFade;
vec4 result;
vec3 tcSafe = texColor.rgb / max(texColor.a, 0.001);
if (blendMode == 0) {
result = vec4(finalColor, 1.0);
} else if (blendMode == 2) {
result = vec4(1.0 - (1.0 - tcSafe) * (1.0 - finalColor), 1.0);
} else {
result = vec4(tcSafe + finalColor, 1.0);
}
result = clamp(result, 0.0, 1.0);
result *= baseAlpha;
vec4 outputColor = mix(texColor, result, alpha);
gl_FragColor = outputColor;
}

float gmHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);}
