// grown from the layer's own pixels and travels with it.
// Positions are anchored on acScreenNorm - the engine's own screen position for
// this fragment - so the anchor never depends on the matrix. Only the DELTA goes
// through acLayerToScreen, and the w=0 multiply cancels the translation, so a
// layer-space offset becomes a screen-space offset exactly. fetchL(acLayerNorm)
// therefore returns texture2DCv(inputImg.texture, acScreenNorm), the engine idiom.
vec2 lpToScreen(vec2 v){ return acScreenNorm + (vec4(v - acLayerNorm, 0.0, 0.0) * acLayerToScreen).xy; }
vec4 fetchL(vec2 lp){ return texture2DCv(inputImg.texture, clamp(lpToScreen(lp), 0.0, 1.0)); }
vec3 strL(vec2 lp){ vec4 s = fetchL(lp); return s.rgb / max(s.a, 1e-4); }

float h21(vec2 p){ return fract(sin(dot(p + seed * 1.61, vec2(127.1, 311.7))) * 43758.5453123); }
float h22(vec2 p){ return fract(sin(dot(p + seed * 1.61, vec2(269.5, 183.3))) * 43758.5453123); }

float vnoise(vec2 p){
vec2 i = floor(p);
vec2 f = fract(p);
f = f * f * (3.0 - 2.0 * f);
return mix(mix(h21(i), h21(i + vec2(1.0, 0.0)), f.x),
           mix(h21(i + vec2(0.0, 1.0)), h21(i + vec2(1.0, 1.0)), f.x), f.y);
}

float fbm(vec2 p){
float s = 0.0;
float amp = 0.5;
for (int i = 0; i < 6; i++){
if (float(i) >= complexity) break;
s += amp * vnoise(p);
p *= 2.05;
amp *= 0.5;
}
return s;
}

// F1, F2 and the winning cell, packed so the whole search stays in one call.
vec4 cellField(vec2 p){
vec2 i = floor(p);
vec2 f = fract(p);
float d1 = 8.0;
float d2 = 8.0;
vec2  bid = i;
for (int j = -1; j <= 1; j++){
for (int k = -1; k <= 1; k++){
vec2 n  = vec2(float(k), float(j));
vec2 c  = i + n;
vec2 pt = n + vec2(0.5) + (vec2(h21(c), h22(c)) - 0.5) * 0.85;
float d = length(pt - f);
if (d < d1){ d2 = d1; d1 = d; bid = c; }
else if (d < d2){ d2 = d; }
}
}
return vec4(d1, d2, bid);
}

void main(){
vec2 lp  = acLayerNorm;
vec4 src = fetchL(lp);

float al = max(src.a, 1.0e-4);
vec3 sc = src.rgb / al;

float asp = acLayerSize.x / max(acLayerSize.y, 1.0);

// ---- field --------------------------------------------------------------
// Pulse stretches the whole lattice, which is what makes it breathe rather than
// just fade - the cells genuinely change size.
float pulseF = 1.0 + sin(acTime * pulseSpeed) * clamp(pulse, 0.0, 1.0) * 0.25;
float cells  = max(acLayerSize.y / max(scale, 1.0), 1.0) * pulseF;

vec2 g = vec2(lp.x * asp, lp.y) * cells;

// Sinew stretches the lattice along one axis so the cells become long fibres.
if (organicMode >= 5){
g.y *= 3.2;
}

// Complexity folds low-frequency noise into the lattice, which breaks the
// regularity of the jitter without needing a bigger search.
if (complexity > 1.0){
g += vec2(fbm(g * 0.5), fbm(g * 0.5 + 7.7)) * (complexity - 1.0) * 0.14;
}

vec4  W = cellField(g);
float d1 = W.x;
float d2 = W.y;
vec2  bid = W.zw;

vec2 jit = (vec2(h21(bid), h22(bid)) - 0.5) * 0.85;
vec2 bc  = bid + vec2(0.5) + jit;
vec2 f   = fract(g);
vec2 rel = f - (bc - floor(g));

// ---- veins and membrane -------------------------------------------------
// F2 - F1 is zero exactly on a cell wall and grows inward, so it is a distance
// field to the wall that needs no extra taps.
float border = max(d2 - d1, 0.0);
float vw = veinWidth * (1.0 + (h21(bid) - 0.5) * cellVar * 1.6);
float vein = 1.0 - smoothstep(0.0, max(vw, 0.002), border);
float mem  = smoothstep(0.0, 0.05, border) * (1.0 - smoothstep(0.05, 0.18, border));

// ---- tissue distortion --------------------------------------------------
// Pull the source outward from the cell centre. Veins pull hardest, so the
// walls read as thicker tissue rather than as drawn lines.
vec2 dpos = lp;
if (distortion > 0.0005){
vec2 dir = rel / max(cells, 1.0e-4);
dpos = lp + dir * distortion * (1.0 + vein * 1.8);
}

vec3 base = strL(dpos);

// ---- shade and colour ---------------------------------------------------
float dome = sqrt(max(1.0 - clamp(d1 * 2.0, 0.0, 1.0), 0.0));
base *= 0.62 + 0.62 * dome;

vec3 tint = mix(cellCol.rgb, veinCol.rgb, vein);
base = mix(base, tint * (0.55 + 0.85 * lum(base)), clamp(colourShift, 0.0, 1.0));

base += veinCol.rgb * vein * veinGlow * 0.85;
base += vec3(mem * membrane * 0.55);

// Mode tweaks: lean on whichever element the preset is named after.
if (organicMode >= 1 && organicMode <= 1){
base += veinCol.rgb * vein * 0.35;
}
if (organicMode >= 2 && organicMode <= 2){
base += vec3(mem * 0.55);
}
if (organicMode >= 3 && organicMode <= 3){
base *= 1.0 + vein * 0.25;
}
if (organicMode >= 4 && organicMode <= 4){
base *= 0.85 + 0.45 * fbm(g * 1.7);
}

base = sat3v(base);
vec3  col = mix(sc, base, mixAmt);
float oA  = src.a * opacity;
gl_FragColor = vec4(col * oA, oA);
}

float gT = 0.0;

vec3 sat3v(vec3 c){ return clamp(c, vec3(0.0), vec3(1.0)); }

// LAYER -> SCREEN. The lattice is built in layer space, so the particles are
// cut from the layer's own pixels and follow the layer's transform.
// Positions are anchored on acScreenNorm - the engine's own screen position for
// this fragment - so the anchor never depends on the matrix. Only the DELTA goes
// through acLayerToScreen, and the w=0 multiply cancels the translation, so a
// layer-space offset becomes a screen-space offset exactly. fetchL(acLayerNorm)
// therefore returns texture2DCv(inputImg.texture, acScreenNorm), the engine idiom.
vec2 lpToScreen(vec2 v){ return acScreenNorm + (vec4(v - acLayerNorm, 0.0, 0.0) * acLayerToScreen).xy; }
vec4 fetchL(vec2 lp){ return texture2DCv(inputImg.texture, clamp(lpToScreen(lp), 0.0, 1.0)); }
vec3 strL(vec2 lp){ vec4 s = fetchL(lp); return s.rgb / max(s.a, 1e-4); }

float h21(vec2 p){ return fract(sin(dot(p + seed * 2.77, vec2(127.1, 311.7))) * 43758.5453123); }
float h22(vec2 p){ return fract(sin(dot(p + seed * 2.77, vec2(269.5, 183.3))) * 43758.5453123); }

vec2 rot2(vec2 p, float a){ float c = cos(a); float s = sin(a); return vec2(p.x * c - p.y * s, p.x * s + p.y * c); }

// One particle's displacement, in cell units. Every mode shares the gravity and
// turbulence tail so those two controls work whatever behaviour is selected.
vec2 particleMotion(vec2 c, vec2 h){
vec2 d = normalize(c - vec2(0.5) + vec2(1.0e-4));
vec2 m = vec2(0.0);

if (particleMode <= 0){
m = d * gT * speed * 0.30;
} else if (particleMode <= 1){
m = vec2(0.0, -gT * speed * 0.30);
} else if (particleMode <= 2){
m = d * gT * speed * 0.55;
} else if (particleMode <= 3){
m = vec2(-d.y, d.x) * gT * speed * 0.28;
} else if (particleMode <= 4){
m = vec2(0.0, gT * speed * 0.45);
} else {
m = rot2(d, gT * speed * 0.90) * 0.16;
}

m += vec2(0.0, gravity * gT * gT * 0.20);

if (turbulence > 0.001){
m += vec2(sin(gT * 1.30 + h.x * 6.2831853),
          cos(gT * 1.10 + h.y * 6.2831853)) * turbulence * 0.12;
}
return m;
}

void main(){
vec2 lp  = acLayerNorm;
vec4 src = fetchL(lp);

float al = max(src.a, 1.0e-4);
vec3 sc = src.rgb / al;

gT = acTime;

float asp = acLayerSize.x / max(acLayerSize.y, 1.0);
vec2  c0  = centre - vec2(0.5);
c0.x *= asp;
vec2  q   = lp - vec2(0.5);
q.x *= asp;
q -= c0;

float cells = max(density, 4.0);
vec2  g = q * cells;
vec2  id = floor(g);
vec2  f  = fract(g);

// ---- nearest particle over the 3x3 neighbourhood -----------------------
float bd  = 9.0;
vec2  bid = id;
for (int j = -1; j <= 1; j++){
for (int i = -1; i <= 1; i++){
vec2 n  = vec2(float(i), float(j));
vec2 c  = id + n;
vec2 h  = vec2(h21(c), h22(c));
vec2 pt = n + vec2(0.5) + (h - 0.5) * spread + particleMotion(c, h);
float d = length(pt - f);
if (d < bd){ bd = d; bid = c; }
}
}

// ---- this particle's own values ----------------------------------------
vec2 hb   = vec2(h21(bid), h22(bid));
vec2 bpos = (bid - id) + vec2(0.5) + (hb - 0.5) * spread + particleMotion(bid, hb);
vec2 mdir = particleMotion(bid, hb);

float hv = hb.x;
float rad = size * cells * (1.0 + (hv - 0.5) * sizeVar);

// ---- anisotropic trail --------------------------------------------------
// Squash the distance along the direction of travel: that is a streak. The
// squared term is written out by hand because pow() with a negative base is
// undefined in GLSL ES.
vec2 rel = f - bpos;
float dEff = bd;
if (trails > 0.001){
float ml = length(mdir);
if (ml > 1.0e-4){
vec2  md    = mdir / ml;
float along = dot(rel, md) / (1.0 + trails * 5.0);
float perp  = dot(rel, vec2(-md.y, md.x));
dEff = sqrt(perp * perp + along * along);
}
}

float aa  = 0.004;
float cov = 1.0 - smoothstep(rad - aa, rad + aa, dEff);
float halo = 1.0 - smoothstep(rad, rad + max(glow, 0.001) * 0.09, dEff);

// ---- birth / death ------------------------------------------------------
// Each particle has its own phase, so they do not all pop in together.
float age  = fract(gT / max(lifetime, 0.1) + hv);
float live = smoothstep(0.0, 0.12, age) * (1.0 - smoothstep(0.65, 1.0, age));

// ---- colour ------------------------------------------------------------
// Back to layer space: undo the aspect correction on x and re-add the lattice
// centre, so the particle's colour is read from where it actually sits.
vec2 plp = (bid + vec2(0.5)) / cells;
plp.x /= asp;
plp += centre;
vec3 pcol = strL(plp) * colourBoost * (0.65 + 0.75 * hv);

vec3 pv = pcol * cov * live;
pv += pcol * halo * glow * 0.35 * live;

// ---- composite ----------------------------------------------------------
// The layer stays behind at a controlled strength so the effect reads as the
// picture breaking into particles rather than as particles on a black plate.
vec3 bg = sc * background;
vec3 v  = bg + pv;

v = sat3v(v);
vec3  col = mix(sc, v, mixAmt);
float oA  = src.a * opacity;
gl_FragColor = vec4(col * oA, oA);
}

float getLuma(vec4 color) {
return dot(color.rgb, vec3(0.299, 0.587, 0.114));
}
void main() {
vec2 uv = acScreenNorm;
vec4 texColor = texture2DCv(inputImg.texture, uv);
float baseAlpha = texColor.a;
vec2 pixelSize = (vec2(edgeThickness) / acScreenSize);
float top = getLuma(texture2DCv(inputImg.texture, uv + vec2(0.0, -pixelSize.y)));
float bottom = getLuma(texture2DCv(inputImg.texture, uv + vec2(0.0, pixelSize.y)));
float left = getLuma(texture2DCv(inputImg.texture, uv + vec2(-pixelSize.x, 0.0)));
float right = getLuma(texture2DCv(inputImg.texture, uv + vec2(pixelSize.x, 0.0)));
float edgeX = right - left;
float edgeY = bottom - top;
float edge = sqrt(edgeX * edgeX + edgeY * edgeY);
edge = smoothstep(edgeThreshold, edgeThreshold + 0.1, edge);
float animMask = 1.0;
if (animate) {
float wave = sin(uv.x * 20.0 + uv.y * 20.0 - acTime * speed);
animMask = smoothstep(0.0, 0.5, wave);
}
float traceStrength = edge * animMask * glowIntensity;
vec3 finalColor = traceColor.rgb * traceStrength;
vec4 result;
vec3 tcSafe = texColor.rgb / max(texColor.a, 0.001);
if (blendMode == 0) {
result = vec4(finalColor, 1.0);
} else if (blendMode == 2) {
result = vec4(1.0 - (1.0 - tcSafe) * (1.0 - finalColor), 1.0);
} else {
result = vec4(tcSafe + finalColor, 1.0);
}
result = clamp(result, 0.0, 1.0);
result *= baseAlpha;
vec4 outputColor = mix(texColor, result, alpha);
gl_FragColor = outputColor;
}

void main() {
vec2 uv = acScreenNorm;
vec4 base = texture2DCv(inputImg.texture, uv);
vec2 offsetR = vec2(amount, amount);
vec2 offsetB = vec2(-amount, -amount);
float r = texture2DCv(inputImg.texture, uv + offsetR * blur).r;
float g = base.g;
float b = texture2DCv(inputImg.texture, uv + offsetB * blur).b;
gl_FragColor = vec4(r, g, b, base.a);
}

const float GM_K=1.73205080757;
