#define EPS 0.00001
#define PI 3.14159265359
float lum(vec3 c) {
return dot(c, vec3(0.2126, 0.7152, 0.0722));
}
vec3 rgb2hsl(vec3 c) {
float mx = max(c.r, max(c.g, c.b));
float mn = min(c.r, min(c.g, c.b));
float l = (mx + mn) * 0.5;
float d = mx - mn;
float s = 0.0;
float h = 0.0;
if (d > EPS) {
s = (l > 0.5) ? d / max(2.0 - mx - mn, EPS) : d / max(mx + mn, EPS);
if (mx == c.r) { h = (c.g - c.b) / d + (c.g < c.b ? 6.0 : 0.0); }
else if (mx == c.g) { h = (c.b - c.r) / d + 2.0; }
else { h = (c.r - c.g) / d + 4.0; }
h /= 6.0;
}
return vec3(h, s, l);
}
float h2r(float p, float q, float t) {
if (t < 0.0) t += 1.0;
if (t > 1.0) t -= 1.0;
if (t < 1.0/6.0) return p + (q - p) * 6.0 * t;
if (t < 0.5) return q;
if (t < 2.0/3.0) return p + (q - p) * (2.0/3.0 - t) * 6.0;
return p;
}
vec3 hsl2rgb(vec3 c) {
if (c.y < EPS) return vec3(c.z);
float q = (c.z < 0.5) ? c.z * (1.0 + c.y) : c.z + c.y - c.z * c.y;
float p = 2.0 * c.z - q;
return vec3(h2r(p,q,c.x+1.0/3.0), h2r(p,q,c.x), h2r(p,q,c.x-1.0/3.0));
}
float getTaps(float q) {
if (q < 1.5) return 10.0;
if (q < 2.5) return 18.0;
return 28.0;
}
vec4 separableBlur(sampler2D tex, vec2 uv, vec2 dir, float radius, float taps) {
if (radius <= 0.5) return texture2DCv(tex, uv);
float sigma = radius / 2.14596602;
sigma = max(sigma, EPS);
float baseCoeff = 1.0 / (sqrt(2.0 * PI) * sigma);
float decayRate = exp(-0.5 / (sigma * sigma));
float decaySq = decayRate * decayRate;
vec4 acc = texture2DCv(tex, uv) * baseCoeff;
float wSum = baseCoeff;
float coeff = baseCoeff;
float decay = decayRate;
for (float i = 1.0; i <= 64.0; i += 2.0) {
if (i > taps) break;
float p0 = i;
float p1 = i + 1.0;
coeff *= decay;
wSum += 2.0 * coeff;
float w0 = coeff;
coeff *= decay;
decay *= decaySq;
wSum += 2.0 * coeff;
float w1 = coeff;
float wPair = w0 + w1;
float oPair = (p0*w0 + p1*w1) / max(wPair, EPS);
vec2 uvA = clamp(uv - oPair * dir, 0.0, 1.0);
vec2 uvB = clamp(uv + oPair * dir, 0.0, 1.0);
acc += texture2DCv(tex, uvA) * wPair;
acc += texture2DCv(tex, uvB) * wPair;
}
return acc / max(wSum, EPS);
}
float detectEdgeLuminance(vec2 uv, vec2 px, float thick) {
vec2 o = px * thick;
float c = lum(texture2DCv(inputImg.texture, uv).rgb);
float t = lum(texture2DCv(inputImg.texture, clamp(uv + vec2(0.0, -o.y), 0.0, 1.0)).rgb);
float b = lum(texture2DCv(inputImg.texture, clamp(uv + vec2(0.0, o.y), 0.0, 1.0)).rgb);
float l = lum(texture2DCv(inputImg.texture, clamp(uv + vec2(-o.x, 0.0), 0.0, 1.0)).rgb);
float r = lum(texture2DCv(inputImg.texture, clamp(uv + vec2(o.x, 0.0), 0.0, 1.0)).rgb);
float edge = abs(t - b) + abs(l - r);
return edge;
}
float detectEdgeSobel(vec2 uv, vec2 px, float thick) {
vec2 o = px * thick;
float tl = lum(texture2DCv(inputImg.texture, clamp(uv + vec2(-o.x, -o.y), 0.0, 1.0)).rgb);
float tc = lum(texture2DCv(inputImg.texture, clamp(uv + vec2(0.0, -o.y), 0.0, 1.0)).rgb);
float tr = lum(texture2DCv(inputImg.texture, clamp(uv + vec2(o.x, -o.y), 0.0, 1.0)).rgb);
float ml = lum(texture2DCv(inputImg.texture, clamp(uv + vec2(-o.x, 0.0), 0.0, 1.0)).rgb);
float mr = lum(texture2DCv(inputImg.texture, clamp(uv + vec2(o.x, 0.0), 0.0, 1.0)).rgb);
float bl = lum(texture2DCv(inputImg.texture, clamp(uv + vec2(-o.x, o.y), 0.0, 1.0)).rgb);
float bc = lum(texture2DCv(inputImg.texture, clamp(uv + vec2(0.0, o.y), 0.0, 1.0)).rgb);
float br = lum(texture2DCv(inputImg.texture, clamp(uv + vec2(o.x, o.y), 0.0, 1.0)).rgb);
float gx = -tl - 2.0*ml - bl + tr + 2.0*mr + br;
float gy = -tl - 2.0*tc - tr + bl + 2.0*bc + br;
return sqrt(gx*gx + gy*gy);
}
float detectEdgeColor(vec2 uv, vec2 px, float thick) {
vec2 o = px * thick;
vec3 c = texture2DCv(inputImg.texture, uv).rgb;
vec3 t = texture2DCv(inputImg.texture, clamp(uv + vec2(0.0, -o.y), 0.0, 1.0)).rgb;
vec3 b = texture2DCv(inputImg.texture, clamp(uv + vec2(0.0, o.y), 0.0, 1.0)).rgb;
vec3 l = texture2DCv(inputImg.texture, clamp(uv + vec2(-o.x, 0.0), 0.0, 1.0)).rgb;
vec3 r = texture2DCv(inputImg.texture, clamp(uv + vec2(o.x, 0.0), 0.0, 1.0)).rgb;
float edge = length(t - b) + length(l - r);
return edge;
}
float detectEdgeDepthLike(vec2 uv, vec2 px, float thick) {
vec2 o = px * thick * 2.0;
float c = lum(texture2DCv(inputImg.texture, uv).rgb);
float t = lum(texture2DCv(inputImg.texture, clamp(uv + vec2(0.0, -o.y), 0.0, 1.0)).rgb);
float b = lum(texture2DCv(inputImg.texture, clamp(uv + vec2(0.0, o.y), 0.0, 1.0)).rgb);
float l = lum(texture2DCv(inputImg.texture, clamp(uv + vec2(-o.x, 0.0), 0.0, 1.0)).rgb);
float r = lum(texture2DCv(inputImg.texture, clamp(uv + vec2(o.x, 0.0), 0.0, 1.0)).rgb);
float laplacian = abs(t + b + l + r - 4.0 * c);
return laplacian * 2.0;
}
void main() {
vec2 uv = acScreenNorm;
float taps = getTaps(float(quality));
if (acPass == 0) {
vec2 px = 1.0 / inputImg.size;
float et = float(edgeType);
float edge = 0.0;
if (et < 1.5) {
edge = detectEdgeLuminance(uv, px, edgeThickness);
} else if (et < 2.5) {
edge = detectEdgeSobel(uv, px, edgeThickness);
} else if (et < 3.5) {
edge = detectEdgeColor(uv, px, edgeThickness);
} else {
edge = detectEdgeDepthLike(uv, px, edgeThickness);
}
edge *= edgeStrength;
float soft = max(edgeSoftness, 0.01);
edge = smoothstep(edgeThreshold - soft * 0.5, edgeThreshold + soft * 0.5, edge);
if (abs(edgeContrast) > EPS) {
float c = 1.0 + edgeContrast;
edge = clamp((edge - 0.5) * c + 0.5, 0.0, 1.0);
}
if (abs(edgeGamma - 1.0) > EPS) {
edge = pow(max(edge, 0.0), 1.0 / max(edgeGamma, EPS));
}
if (edgeBoost > EPS) {
edge = min(edge * (1.0 + edgeBoost), 1.0);
}
if (edgeInvert) {
edge = 1.0 - edge;
}
vec3 srcColor = texture2DCv(inputImg.texture, uv).rgb;
vec3 eColor;
if (useSourceColor) {
eColor = srcColor;
} else {
eColor = edgeColor.rgb;
}
if (abs(edgeSaturation - 1.0) > EPS) {
float eL = lum(eColor);
eColor = mix(vec3(eL), eColor, edgeSaturation);
}
eColor = mix(vec3(1.0), eColor, edgeColorStrength);
vec3 edgeRGB = eColor * edge;
gl_FragColor = vec4(edgeRGB, edge);
return;
}
if (acPass == 1) {
vec2 dir = vec2(1.0 / edgeBuf.size.x, 0.0);
gl_FragColor = separableBlur(edgeBuf.texture, uv, dir, glowRadius, taps);
return;
}
if (acPass == 2) {
vec2 dir = vec2(0.0, 1.0 / glowH.size.y);
gl_FragColor = separableBlur(glowH.texture, uv, dir, glowRadius, taps);
return;
}
vec4 original = texture2DCv(inputImg.texture, uv);
vec3 baseRGB = max(original.rgb, 0.0);
vec4 edgeData = texture2DCv(edgeBuf.texture, uv);
vec3 edgeRGB = edgeData.rgb;
float edgeMask = edgeData.a;
vec4 glowData = texture2DCv(glowV.texture, uv);
vec3 glowRGB = max(glowData.rgb, 0.0);
float glowMask = max(glowData.a, 0.0);
float pulse = 1.0;
if (pulseSpeed > EPS) {
pulse = 1.0 - pulseAmount * 0.5 + pulseAmount * 0.5 * sin(acTime * pulseSpeed * PI * 2.0);
}
vec3 innerG = edgeRGB * innerGlow * pulse;
if (innerSoftness > EPS) {
innerG *= smoothstep(0.0, innerSoftness, edgeMask);
}
if (abs(glowFalloff - 1.0) > EPS) {
glowRGB = pow(max(glowRGB, 0.0), vec3(glowFalloff * 0.5));
}
vec3 outerG = glowRGB * outerGlow * outerSpread * pulse;
vec3 totalGlow = innerG + outerG * glowAmount;
if (colorMapStrength > EPS) {
float glowIntensity = lum(totalGlow);
vec3 mapped;
if (glowIntensity > 0.66) {
float t = (glowIntensity - 0.66) / 0.34;
mapped = mix(glowColorMid.rgb, glowColorCore.rgb, t);
} else if (glowIntensity > 0.33) {
float t = (glowIntensity - 0.33) / 0.33;
mapped = mix(glowColorOuter.rgb, glowColorMid.rgb, t);
} else {
float t = glowIntensity / 0.33;
mapped = mix(vec3(0.0), glowColorOuter.rgb, t);
}
mapped *= max(glowIntensity * 2.0, 0.0);
totalGlow = mix(totalGlow, mapped, colorMapStrength);
}
if (hueRotateSpeed > EPS) {
vec3 glowHSL = rgb2hsl(max(totalGlow, 0.0));
glowHSL.x = fract(glowHSL.x + acTime * hueRotateSpeed);
totalGlow = hsl2rgb(glowHSL);
}
if (edgeOnly) {
gl_FragColor = vec4(clamp(edgeRGB, 0.0, 1.0), edgeMask);
return;
}
if (glowOnly) {
gl_FragColor = vec4(clamp(totalGlow, 0.0, 1.0), clamp(lum(totalGlow) * 3.0, 0.0, 1.0));
return;
}
vec3 composited;
float bm = float(blendMode);
if (bm < 1.5) {
composited = baseRGB + totalGlow;
} else if (bm < 2.5) {
composited = 1.0 - (1.0 - baseRGB) * (1.0 - clamp(totalGlow, 0.0, 1.0));
} else if (bm < 3.5) {
vec3 gS = clamp(totalGlow, 0.0, 1.0);
vec3 r;
r.r = (gS.r<0.5) ? 2.0*baseRGB.r*gS.r+baseRGB.r*baseRGB.r*(1.0-2.0*gS.r) : 2.0*baseRGB.r*(1.0-gS.r)+sqrt(max(baseRGB.r,0.0))*(2.0*gS.r-1.0);
r.g = (gS.g<0.5) ? 2.0*baseRGB.g*gS.g+baseRGB.g*baseRGB.g*(1.0-2.0*gS.g) : 2.0*baseRGB.g*(1.0-gS.g)+sqrt(max(baseRGB.g,0.0))*(2.0*gS.g-1.0);
r.b = (gS.b<0.5) ? 2.0*baseRGB.b*gS.b+baseRGB.b*baseRGB.b*(1.0-2.0*gS.b) : 2.0*baseRGB.b*(1.0-gS.b)+sqrt(max(baseRGB.b,0.0))*(2.0*gS.b-1.0);
composited = r;
} else {
composited = mix(baseRGB, totalGlow, clamp(lum(totalGlow) * 2.0, 0.0, 1.0));
}
if (ditherAmt > EPS) {
vec2 px = floor(inputImg.size * uv);
float n1 = fract(sin(dot(px, vec2(12.9898, 78.233))) * 43758.5453);
float n2 = fract(sin(dot(px, vec2(24.123, 17.321))) * 12345.6789);
float n3 = fract(sin(dot(px, vec2(93.989, 67.345))) * 98765.4321);
composited += (vec3(n1, n2, n3) - 0.5) * ditherAmt;
}
composited = mix(baseRGB, composited, globalMix);
composited = clamp(composited, 0.0, 1.0);
gl_FragColor = vec4(composited, original.a);
}

#define PI 3.14159265359
#define GOLDEN_ANGLE 2.3999632
mat2 rot2m(float a) {
float s = sin(a);
float c = cos(a);
return mat2(c, -s, s, c);
}
float irisMask(vec2 p, float sides, float curvature) {
float r = length(p);
if (r == 0.0) return 1.0;
float angle = atan(p.y, p.x);
float sector = 2.0 * PI / sides;
float a = mod(angle, sector) - 0.5 * sector;
float radiusEdge = cos(0.5 * sector) / cos(a);
float t = clamp(curvature * 0.5 + 0.5, 0.0, 1.0);
radiusEdge = mix(radiusEdge, 1.0, t);
float m = smoothstep(radiusEdge, radiusEdge - 0.02, r);
return m;
}
float focusFactor(vec2 uv) {
if (FOCUS_RADIUS <= 0.0) return 1.0;
vec2 focusPoint = vec2(FOCUS_X, FOCUS_Y);
float d = distance(uv, focusPoint);
float inner = FOCUS_RADIUS;
float outer = FOCUS_RADIUS + FOCUS_SOFTNESS;
outer = max(outer, inner + 0.001);
return smoothstep(inner, outer, d);
}
vec3 LensBokeh(sampler2D tex, vec2 uv, float radiusNorm) {
if (radiusNorm <= 0.0) {
return texture2DCv(tex, uv).rgb;
}
float iter = max(1.0, float(ITERATIONS));
vec2 vangle = vec2(0.0, radiusNorm / sqrt(iter));
vec3 acc = vec3(0.0);
vec3 div = vec3(0.0);
float r = 1.0;
float sides = max(3.0, IRIS_SIDES);
bool usePolygon = (IRIS_MODE == 1);
float irisRad = radians(IRIS_ROTATION);
mat2 irisRotM = rot2m(irisRad);
mat2 rot = rot2m(GOLDEN_ANGLE);
for (float j = 0.0; j < float(ITERATIONS); j++) {
r += 1.0 / r;
vangle = rot * vangle;
vec2 offset = (r - 1.0) * vangle;
vec2 pNorm = offset / radiusNorm;
pNorm *= vec2(SCALE_X, SCALE_Y);
pNorm = irisRotM * pNorm;
float mask = 1.0;
if (usePolygon) {
mask = irisMask(pNorm, sides, IRIS_CURVATURE);
}
if (mask <= 0.0) continue;
float dist = clamp(length(pNorm), 0.0, 1.0);
float shade = mix(1.0, 1.0 - dist, BOKEH_SHADING);
vec3 col = texture2DCv(tex, uv + offset).rgb;
vec3 w = pow(col, vec3(GAMMA));
acc += col * w * mask * shade;
div += w * mask * shade;
}
float divSum = div.x + div.y + div.z;
if (divSum <= 0.0) {
return texture2DCv(tex, uv).rgb;
}
return acc / div;
}
void main() {
vec2 uv = acScreenNorm;
vec4 texColor = texture2DCv(inputImg.texture, uv);
float baseRadiusNorm = RADIUS * progressa * 0.01;
float fFactor = focusFactor(uv);
float radiusNorm = baseRadiusNorm * fFactor;
vec3 blurRGB = LensBokeh(inputImg.texture, uv, radiusNorm);
vec4 blurColor = vec4(blurRGB, texColor.a);
vec4 factor = mix(texColor, blurColor, alpha);
vec4 resultfinal;
if (blendMode == 0) {
resultfinal = factor * bright;
resultfinal.a = texColor.a;
} else if (blendMode == 1) {
factor *= bright;
vec4 c = factor + vec4(1.0) * (1.0 - factor.a);
resultfinal = vec4((texColor.rgb / max(texColor.a, 1e-3)) * c.rgb, 1.0) * texColor.a;
} else if (blendMode == 2) {
factor *= bright;
vec3 src = texColor.rgb / max(texColor.a, 1e-3);
vec3 scr = 1.0 - ((1.0 - src) * (1.0 - factor.rgb));
resultfinal = vec4(scr, 1.0) * texColor.a;
}
gl_FragColor = resultfinal;
}

#define DEG2RAD 0.01745329251994329576923690768489
vec2 l2s( vec2 v ) {
return (vec4(v,0.,1.)*acLayerToScreen).xy;
}
vec2 bend(vec2 p, float a, float l, float w, bool vertical) {
if( abs(a)<0.001 )
{
float v = p.y;
p.y -= clamp(p.y,0.0,l);
return vec2(p.x, v);
}
vec2  sc = vec2(sin(a),cos(a));
if(vertical) {
float ra = 0.5*l/a;
p.x -= ra;
float s = sign(a);
float u = abs(ra)-length(p);
float v = ra*atan(s*p.y,-s*p.x);
u *= s;
return vec2(u, v);
}
else {
float ra = 0.5*w/a;
p.y -= ra;
float s = sign(a);
float v = abs(ra)-length(p);
float u = ra*atan(s*p.x,-s*p.y);
v *= s;
return vec2(u, v);
}
}
void main() {
vec2 a;
vec2 b;
vec2 c = vec2(0);
bool vertical;
float angleVal = amount;
float originOffset = offset;
float adjOffset = offset * 0.99;
if( originType==0 ) {
a = vec2(adjOffset,0.5);
b = vec2(1.0,0.5);
c = vec2(0.0, 0.5);
vertical = false;
} else if( originType==1 ) {
a = vec2(1.0 - adjOffset,0.5);
b = vec2(0.0,0.5);
c = vec2(1.0, 0.5);
vertical = false;
angleVal = -amount;
} else if( originType==2 ) {
a = vec2(0.5,1.0 - adjOffset);
b = vec2(0.5,0.0);
c = vec2(0.5, 1.0);
vertical = true;
} else if( originType==3 ) {
a = vec2(0.5,adjOffset);
b = vec2(0.5,1.0);
c = vec2(0.5, 0.0);
vertical = true;
angleVal = -amount;
}
vec2 a2b = b - a;
vec2 a2c = acLayerNorm - a;
float checkOffset = dot(a2b, a2c);
if(checkOffset < 0.0) {
if(oppositeType == 0 || adjOffset <= 0.0 ) {
gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm);
return;
}
else {
if(adjOffset < lowLimit)
angleVal *= (adjOffset / lowLimit);
b = c;
a2b = b - a;
angleVal = angleVal;
if(oppositeType == 2)
angleVal = -angleVal;
}
}
else {
if(adjOffset >= highLimit * 0.99)
angleVal *= (1.0 - (adjOffset - highLimit * 0.99) / (0.99 - highLimit * 0.99));
}
angleVal = angleVal*DEG2RAD*0.5 / length(a2b);
vec2 vv = acLayerNorm;
vec2 av = a;
if(vertical) {
vv.x *= (acLayerSize.x/acLayerSize.y);
av.x *= (acLayerSize.x/acLayerSize.y);
vec2 uv = bend(vv-av,angleVal,1.0,1.0, vertical);
uv.x *= acLayerSize.y/acLayerSize.x;
av.x *= acLayerSize.y/acLayerSize.x;
uv=l2s(uv+av);
float insideTexture = step(0.0,uv.x) * step(uv.x,1.0) * step(0.0,uv.y) * step(uv.y,1.0);
gl_FragColor = texture2DCv(inputImg.texture, uv) * insideTexture;
}
else {
vv.y *= (acLayerSize.y/acLayerSize.x);
av.y *= (acLayerSize.y/acLayerSize.x);
vec2 uv = bend(vv-av,angleVal,1.0,1.0, vertical);
uv.y *= acLayerSize.x/acLayerSize.y;
av.y *= acLayerSize.x/acLayerSize.y;
uv=l2s(uv+av);
float insideTexture = step(0.0,uv.x) * step(uv.x,1.0) * step(0.0,uv.y) * step(uv.y,1.0);
gl_FragColor = texture2DCv(inputImg.texture, uv) * insideTexture;
}
}

const float PI = 3.141592653589793;
void main(){
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
vec2 texel = 1.0 / inputImg.size;
float a_t = texture2DCv(inputImg.texture, uv + vec2(0.0,  texel.y)).a;
float a_b = texture2DCv(inputImg.texture, uv + vec2(0.0, -texel.y)).a;
float a_r = texture2DCv(inputImg.texture, uv + vec2( texel.x, 0.0)).a;
float a_l = texture2DCv(inputImg.texture, uv + vec2(-texel.x, 0.0)).a;
vec2 grad = vec2(a_r - a_l, a_t - a_b);
float edgeStrength = length(grad);
float bevelAngle = radians(135.0);
vec2 lightDir = normalize(vec2(cos(bevelAngle), sin(bevelAngle)));
float lighting = dot(normalize(grad + 1e-6), lightDir);
float thickness = edgeThickness * 0.01;
float bevelMask = smoothstep(0.0, thickness + 1e-6, edgeStrength);
float softness = 0.5;
float powExp = 1.0 + (1.0 - softness) * 4.0;
float highlight = pow(max(0.0,  lighting), powExp);
float shadow    = pow(max(0.0, -lighting), powExp);
float edgeGain = edgeIntensity / 100.0;
vec3 beveled = src.rgb;
beveled = mix(beveled, vec3(1.0), highlight * bevelMask * edgeGain);
beveled = mix(beveled, vec3(0.0), shadow    * bevelMask * edgeGain);
vec2 centerPx = center;
vec2 centerUV = centerPx / acScreenSize;
vec2 p = uv - centerUV;
p.x *= acScreenSize.x / max(acScreenSize.y, 1.0);
float ang = radians(directionDeg);
vec2 dir = vec2(cos(ang), sin(ang));
vec2 nrm = vec2(-dir.y, dir.x);
float width = widthPx / max(acScreenSize.y, 1.0);
float d = abs(dot(p, nrm));
float beam = pow(1.0 - smoothstep(0.0, width, d), 8.0);
float glow = (1.0 - smoothstep(0.0, width * 5.0, d)) * 0.4;
float sweep = (beam + glow) * (sweepIntensity / 25.0);
sweep += bevelMask * beam * 2.0;
vec3 sweepCol = lightColor.rgb * sweep;
vec3 outRGB;
if(int(lightReception)==0){
outRGB = beveled + sweepCol;
} else {
outRGB = 1.0 - (1.0 - beveled) * (1.0 - sweepCol);
}
vec2 n = normalize(grad + 1e-6);
float rimWidth = rimWidthPx / max(acScreenSize.y, 1.0);
float rang = radians(rimAngleDeg);
vec2 rn = vec2(cos(rang) * n.x - sin(rang) * n.y, sin(rang) * n.x + cos(rang) * n.y);
float a_in_rim = texture2DCv(inputImg.texture, uv - rn * rimWidth).a;
float rimBand = clamp(src.a - a_in_rim, 0.0, 1.0);
rimBand = smoothstep(0.0, 0.6, rimBand);
vec3 rimCol = rimColor.rgb * rimBand * (rimIntensity / 100.0);
if(int(rimReception)==0){
outRGB += rimCol;
} else {
outRGB = 1.0 - (1.0 - outRGB) * (1.0 - rimCol);
}
float innerWidth = innerWidthPx / max(acScreenSize.y, 1.0);
float a_in_inner = texture2DCv(inputImg.texture, uv - n * innerWidth).a;
float innerBand = clamp(src.a - a_in_inner, 0.0, 1.0);
innerBand = 1.0 - exp(-innerBand * 3.0);
vec3 innerCol = innerColor.rgb * innerBand * (innerIntensity / 100.0);
if(int(innerReception)==0){
outRGB += innerCol;
} else {
outRGB = 1.0 - (1.0 - outRGB) * (1.0 - innerCol);
}
float aOut = src.a * alpha;
gl_FragColor = vec4(outRGB, 1.0) * aOut;
}

