vec3 sumR=vec3(0.0), sum2R=vec3(0.0), minR=vec3(1e9), maxR=vec3(-1e9);
int count=0;
for(int y=0;y<MAXN;y++){
if(y>=N) break;
for(int x=0;x<MAXN;x++){
if(x>=N) break;
if(halfFlag && mod(float(x+y),2.0)>0.5) continue;
vec2 p=(vec2(float(x)+0.5,float(y)+0.5)/float(N));
