vec4 applyMinimax(sampler2D tex, vec2 coord, vec2 step, int operation, int channel) {
vec2 texelSize = 1.0 / inputImg.size;
int r = int(radius);
vec4 result = texture2DCv(tex, coord);
for (int i = -50; i <= 50; i++) {
if (i < -r || i > r) continue;
vec2 offset = step * float(i) * texelSize;
vec4 s = texture2DCv(tex, coord + offset);
if (channel == 4) {
if (operation == 1) {
result = max(result, s);
} else {
result = min(result, s);
}
} else {
float rv = (channel == 0) ? result.r :
(channel == 1) ? result.g :
(channel == 2) ? result.b : result.a;
float sv = (channel == 0) ? s.r :
(channel == 1) ? s.g :
(channel == 2) ? s.b : s.a;
if (operation == 1) {
if (sv > rv) result = s;
} else {
if (sv < rv) result = s;
}
}
}
return result;
}
