float smoothNoise(float t, float s) {
float i = floor(t);
float f = fract(t);
float a = hash(i + s);
float b = hash(i + 1.0 + s);
float c = hash(i + 2.0 + s);
float d = hash(i + 3.0 + s);
float f2 = f * f;
float f3 = f2 * f;
float cr0 = -0.5*a + 1.5*b - 1.5*c + 0.5*d;
float cr1 = a - 2.5*b + 2.0*c - 0.5*d;
float cr2 = -0.5*a + 0.5*c;
float cr3 = b;
return cr0*f3 + cr1*f2 + cr2*f + cr3;
}
float layeredNoise(float t, float s, float smooth_amt) {
float n = 0.0;
float amp = 1.0;
float totalAmp = 0.0;
float freq = 1.0;
int layers = 4;
for (int i = 0; i < 4; i++) {
float fi = float(i);
float layerSeed = s + fi * 17.31;
float rawNoise = smoothNoise(t * freq, layerSeed) * 2.0 - 1.0;
n += rawNoise * amp;
totalAmp += amp;
amp *= mix(0.6, 0.3, smooth_amt);
freq *= mix(2.1, 1.7, smooth_amt);
}
return n / max(totalAmp, EPS);
}
float getRandomShake(float time, float freq, float phase, float seedOffset, float smooth_amt) {
float t = (time + phase) * freq;
float s = seed + seedOffset;
return layeredNoise(t, s, smooth_amt);
}
float getWaveShake(float time, float freq, float phase) {
return sin((time + phase) * freq * 2.0 * PI);
}
float getShakeAxis(float time, float masterAmp, float masterFreq,
float randAmp, float randFreq,
float waveAmp, float waveFreq,
float phase, float seedOff) {
float result = 0.0;
if (randAmp > EPS) {
float rnd = getRandomShake(time, masterFreq * randFreq, phase, seedOff, smoothness);
result += rnd * randAmp;
}
if (waveAmp > EPS) {
float wav = getWaveShake(time, waveFreq, phase);
result += wav * waveAmp;
}
