float t = time + channelPhase * 0.1;
float shakeX = getShakeAxis(t, amplitude, frequency,
xRandAmp, xRandFreq, xWaveAmp, xWaveFreq,
xPhase, 0.0);
float shakeY = getShakeAxis(t, amplitude, frequency,
yRandAmp, yRandFreq, yWaveAmp, yWaveFreq,
yPhase, 100.0);
float shakeZ = getShakeAxis(t, amplitude, frequency,
zRandAmp, zRandFreq, zWaveAmp, zWaveFreq,
zPhase, 200.0);
float shakeTilt = getShakeAxis(t, amplitude, frequency,
tiltRandAmp, tiltRandFreq, tiltWaveAmp, tiltWaveFreq,
tiltPhase, 300.0);
shakeX += rgbRandX;
shakeY += rgbRandY;
shakeZ += rgbRandZ;
shakeTilt += rgbRandTilt;
shakeX *= channelAmp;
shakeY *= channelAmp;
shakeZ *= channelAmp;
shakeTilt *= channelAmp;
vec2 center = vec2(0.5);
vec2 result = uv - center;
float tiltRad = shakeTilt * PI / 180.0;
float cs = cos(tiltRad);
float sn = sin(tiltRad);
result = vec2(result.x * cs - result.y * sn,
result.x * sn + result.y * cs);
float zoomFactor = 1.0 / max(1.0 + shakeZ, 0.1);
result *= zoomFactor;
result += center;
result.x += shakeX * 0.01;
result.y += shakeY * 0.01;
return result;
}
