}
vec4 composite(vec4 a, vec4 b) {
return a * (1.-b.a) + b;
}
#define M_PI 3.141592
#define CYL_DIST (cyl.z)
vec2 curlFun(float t, float maxt, vec3 cyl) {
vec2 ret = vec2(t, 1.0);
if (t < CYL_DIST - radius)
return ret;
if (t > CYL_DIST + radius)
return vec2(-1.0);
float a = asin((t - CYL_DIST) / radius);
float ca = -a + M_PI;
ret.x = CYL_DIST + ca * radius;
ret.y = cos(ca);
if (ret.x < maxt)
return ret;
if (t < CYL_DIST)
return vec2(t, 1.0);
ret.y = cos(a);
ret.x = CYL_DIST + a * radius;
return ret.x < maxt ? ret : vec2(-1.0);
}
vec2 curlFunFront(float t, float maxt, vec3 cyl) {
vec2 ret = vec2(t, 1.0);
if (t < CYL_DIST - radius)
return ret;
if (t > CYL_DIST + radius)
return vec2(-1.0);
float a = asin((t - CYL_DIST) / radius);
float ca = -a + M_PI;
ret.x = CYL_DIST + ca * radius;
ret.y = cos(ca);
if (t < CYL_DIST)
return vec2(t, 1.0);
ret.y = cos(a);
ret.x = CYL_DIST + a * radius;
return ret.x < maxt ? ret : vec2(-1.0);
}
vec4 blendColor( vec4 base, vec4 color, int mode, float p) {
if( mode == 1 ) {
vec3 aa = base.rgb / max(base.a,0.00001);
vec3 bb = color.rgb / max(color.a,0.00001);
vec3 cc = aa * bb;
vec4 adjColor = vec4(cc,1.) * color.a * p;
return base * (1.-adjColor.a) + adjColor;
} else if( mode == 2 ) {
vec3 aa = base.rgb / max(base.a,0.00001);
vec3 bb = color.rgb / max(color.a,0.00001);
vec3 cc = 1.-((1.-aa) * (1.-bb));
vec4 adjColor = vec4(cc,1.) * color.a * p;
return base * (1.-adjColor.a) + adjColor;
} else {
vec4 adjColor = color * p;
return base * (1.-adjColor.a) + adjColor;
}
}
void main() {
vec2 uv = acLayerNorm;
vec2 ur = vec2(1.0);
float h = sqrt(tan(M_PI/4.-abs(mod(angle*0.0174533,M_PI/2.)-M_PI/4.))+1.);
float d = (1.-progress) * h;
d = 1.-((1.0-d) * (1.+radius));
vec2 cd = vec2(1.0,0.0)*rot2(angle*0.0174533);
vec2 iv = step(cd,vec2(0.));
uv = iv + uv * (1.-iv*2.);
vec3 cyl = vec3(abs(cd),d);
d = dot(uv, cyl.xy);
vec2 end = abs((ur - uv) / cyl.xy);
float maxt = d + min(end.x, end.y);
vec2 cff = curlFunFront(d, maxt, cyl);
vec2 cf = curlFun(d, maxt, cyl);
vec2 tuv = uv + cyl.xy * (cf.x - d);
vec2 tuvf = uv + cyl.xy * (cff.x - d);
tuv /= ur;
tuv = iv + tuv * (1.-iv*2.);
tuvf /= ur;
tuvf = iv + tuvf * (1.-iv*2.);
float shadow = 1.0 - smoothstep (0.0, radius * 2.0, -(d - CYL_DIST));
shadow *= (smoothstep(-radius, radius, (maxt - (cf.x + 1.5 * M_PI * radius + radius))));
vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
vec4 blurColor = texture2DCv(blurBuf.texture,acScreenNorm);
vec4 frontColor = texture2DCv(inputImg.texture,l2s(tuvf));
vec4 result = texture2DCv(inputImg.texture,l2s(tuv));
vec4 front = blendColor(frontColor, frontShadowColor * frontShadowAlpha * frontColor.a, frontShadowBlendMode, clamp(1.0 - cff.y, 0.0, 1.0)  );
result = cf.y > 0.0
? front
: blendColor(
blendColor(
composite(front,mix(texColor * (1.-blurColor.a)+blurColor,result,alpha)),
backColor * backAlpha * result.a, backBlendMode, 1. * step(uv.x,1.) * step(uv.y,1.)
),
shineColor * shineAlpha * result.a, shineBlendMode, pow(-cf.y,shineSpec) * step(uv.x,1.) * step(uv.y,1.)
);
shadow = smoothstep (0.0, radius * 2.0, (d - CYL_DIST));
if(softDropShadow) {
shadow = saturate((1.-shadow)*2.) * (1.-pow(length(acLayerNorm-0.5)*2.,2.) );
vec4 adjShadowColor = dropShadowColor * dropShadowAlpha * shadow * (smoothstep(0.5,1.0,blurColor.a)) * texColor.a;
gl_FragColor = (cf.x > 0.0 ? composite(adjShadowColor,result) : adjShadowColor) * step(uv.x,1.) * step(uv.y,1.);
} else {
gl_FragColor = (cf.x > 0.0 ? result : dropShadowColor * dropShadowAlpha * saturate((1.-shadow)*2.) * texColor.a) * step(uv.x,1.) * step(uv.y,1.);
}
}

float hash12(vec2 p) {
vec3 p3  = fract(vec3(p.xyx) * .1031);
p3 += dot(p3, p3.yzx + 33.33);
return fract((p3.x + p3.y) * p3.z);
}
vec3 getSource(vec2 uv) {
return texture2DCv(inputImg.texture, uv).rgb;
}
float getGray(vec3 c) {
return dot(c, vec3(0.299, 0.587, 0.114));
}
void main() {
vec2 uv = acScreenNorm;
float aspect = acScreenSize.x / acScreenSize.y;
vec2 scale = vec2(frequency * aspect, frequency);
vec2 gridUV = uv * scale;
vec2 gridId = floor(gridUV);
vec3 pixelColor = getSource(uv);
float bestPriority = -1.0;
for (float y = -2.0; y <= 2.0; y++) {
for (float x = -2.0; x <= 2.0; x++) {
vec2 neighbor = vec2(x, y);
vec2 id = gridId + neighbor;
float timeOffset = (jitter > 0.5) ? floor(acTime * 12.0) : 0.0;
vec2 seed = id + vec2(timeOffset * 0.1, timeOffset * 1.618);
vec2 rand = vec2(hash12(seed), hash12(seed + 4.13));
vec2 centerGrid = neighbor + rand;
vec2 centerUV = (id + rand) / scale;
if (centerUV.x < 0.0 || centerUV.x > 1.0 || centerUV.y < 0.0 || centerUV.y > 1.0) continue;
vec3 col = getSource(centerUV);
vec2 eps = vec2(2.0 / acScreenSize.x, 2.0 / acScreenSize.y);
float gC = getGray(col);
float gH = getGray(getSource(centerUV + vec2(eps.x, 0.0)));
float gV = getGray(getSource(centerUV + vec2(0.0, eps.y)));
float dX = gH - gC;
float dY = gV - gC;
float angle = atan(dY, dX) + 1.5708;
vec2 p = fract(gridUV);
vec2 delta = p - centerGrid;
float cs = cos(-angle);
float sn = sin(-angle);
vec2 rotP = vec2(delta.x * cs - delta.y * sn, delta.x * sn + delta.y * cs);
float len = strokeLength * 0.8;
float wid = strokeWidth * 0.3;
float dx = max(abs(rotP.x) - len, 0.0);
float dy = abs(rotP.y);
float dist = length(vec2(dx, dy));
float mask = 1.0 - smoothstep(wid - 0.1, wid + 0.1, dist);
float brushNoise = hash12(rotP * 10.0 + seed);
mask *= 0.8 + 0.2 * brushNoise;
if (mask > 0.01) {
float depth = rand.x;
float priority = depth * mask;
if (priority > bestPriority) {
bestPriority = priority;
pixelColor = col;
pixelColor *= 0.95 + 0.05 * mask;
}
}
}
}
gl_FragColor = vec4(pixelColor, 1.0);
}

vec3 hash3(vec2 p) {
vec3 q = vec3(
dot(p, vec2(127.1, 311.7)),
dot(p, vec2(269.5, 183.3)),
dot(p, vec2(419.2, 371.9))
);
return fract(sin(q) * 43758.5453);
}
float gradientNoise(vec2 p) {
vec2 i = floor(p);
vec2 f = fract(p);
vec2 u = f * f * (3.0 - 2.0 * f);
float n = mix(
mix(
dot(-1.0 + 2.0 * hash3(i).xy, f - vec2(0.0, 0.0)),
dot(-1.0 + 2.0 * hash3(i + vec2(1.0, 0.0)).xy, f - vec2(1.0, 0.0)),
u.x
),
mix(
dot(-1.0 + 2.0 * hash3(i + vec2(0.0, 1.0)).xy, f - vec2(0.0, 1.0)),
dot(-1.0 + 2.0 * hash3(i + vec2(1.0, 1.0)).xy, f - vec2(1.0, 1.0)),
u.x
),
u.y
);
return 0.5 + 0.5 * n;
}
