float featherFactor = (1.-(1./acLayerSize.x*(feather)));
a = (a - 0.5) * featherFactor + 0.5;
float featherDist = (1.0 - featherFactor);
float f0 = smoothStep(0.0,featherDist,a);
float f1 = smoothStep(1.0,1.0-featherDist,a);
a = (a - 0.5) * cropFactor + 0.5;
float cff = cropFactor * featherFactor;
if( feather >= 0.0 && f0+f1 > 0.0 ) {
gl_FragColor = mix( getSample(a+cff,r), mix( getSample(a-cff,r), getSample(a,r), f1 ), f0);
} else {
gl_FragColor = getSample(a,r);
}
}

float h21(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
vec2  h22(vec2 p){ float n = h21(p); return vec2(n, h21(p + n + 7.7)); }
float lumOf(vec3 c){ return dot(c, vec3(0.2126, 0.7152, 0.0722)); }
float sat(float x){ return clamp(x, 0.0, 1.0); }

// LAYER -> SCREEN. The lattice lives in layer space so it inherits the layer's
// transform; every lookup back into the source has to come through here.
vec2 lpToScreen(vec2 v){ return (vec4(v, 0.0, 1.0) * acLayerToScreen).xy; }
vec4 fetchL(vec2 lp){
vec2 halfPixel = 0.5 / max(acLayerSize, vec2(1.0));
return texture2DCv(inputImg.texture, lpToScreen(clamp(lp, halfPixel, 1.0 - halfPixel)));
}
vec3 srcL(vec2 lp){ vec4 c = fetchL(lp); return c.rgb / max(c.a, 1e-4); }

// Central-difference gradient of luminance, in layer units. Four taps, and only
// paid for when the fill mode actually needs it - the old version ran this for
// 25 candidate points per pixel, which is what made the effect unusable.
vec2 gradL(vec2 lp, float e){
vec2 d = vec2(e, 0.0);
float gx = lumOf(srcL(lp + vec2(d.x, 0.0))) - lumOf(srcL(lp - vec2(d.x, 0.0)));
float gy = lumOf(srcL(lp + vec2(0.0, d.x))) - lumOf(srcL(lp - vec2(0.0, d.x)));
return vec2(gx, gy) / max(e * 2.0, 1e-4);
}

vec3 sat3(vec3 c, float s){ float l = lumOf(c); return mix(vec3(l), c, s); }

void main(){
vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
if (mixAmt <= 0.0 || src.a <= 0.0) { gl_FragColor = src * opacity; return; }
vec2 lp  = acLayerNorm;

// Aspect-corrected layer space: the cells stay square whatever the layer is.
float asp = max(acLayerSize.x, 1.0) / max(acLayerSize.y, 1.0);
vec2 lpA  = vec2(lp.x * asp, lp.y);

// One cell is cellPx screen pixels tall measured on the layer, so the lattice
// keeps its physical size when the layer is scaled.
float tiles = max(acLayerSize.y / max(cellPx, 1.0), 1.0);
vec2 g  = lpA * tiles;
vec2 id = floor(g);
vec2 f  = g - id;

// F1 / F2 over the 3x3 neighbourhood. The jitter is held to the middle 72% of
// the cell so the nearest site is always inside the neighbourhood - a full-cell
// jitter lets a site two cells away win and the field then jumps.
float d1 = 9.0; float d2 = 9.0;
vec2  site = vec2(0.5);
vec2  sid  = id;
for (int j = -1; j <= 1; j++){
for (int i = -1; i <= 1; i++){
vec2 n = vec2(float(i), float(j));
vec2 c = id + n;
vec2 sp = n + 0.5 + (h22(c + seed * 3.7) - 0.5) * 0.72 * jitter;
vec2 dv = sp - f;
float d = dot(dv, dv);
if (d < d1){ d2 = d1; d1 = d; site = sp; sid = c; }
else if (d < d2){ d2 = d; }
}
}

// Site back into layer space (undo the aspect correction on x only).
vec2 siteA = (id + site) / tiles;
vec2 siteLp = vec2(siteA.x / asp, siteA.y);

// ---- fill ---------------------------------------------------------------
vec3 cell;
if (fillMode <= 0){
cell = srcL(siteLp);
} else if (fillMode <= 1){
// Pull the sample point along the luminance gradient: shards crowd into the
// detail and stretch flat across empty areas.
float e = 1.5 / max(tiles, 1.0);
vec2 gr = gradL(siteLp, e);
float gl = length(gr);
vec2 dir = (gl < 1e-5) ? vec2(0.0) : gr / gl;
vec2 pull = dir * sat(gl) * gradPull * (0.75 / max(tiles, 1.0));
cell = srcL(siteLp + pull);
} else {
// Five taps inside the cell: a flat average, so the shard reads as one piece
// of the picture rather than a single pixel blown up.
float r = 0.28 / max(tiles, 1.0);
vec3 acc = srcL(siteLp);
acc += srcL(siteLp + vec2( r, 0.0));
acc += srcL(siteLp + vec2(-r, 0.0));
acc += srcL(siteLp + vec2(0.0,  r));
acc += srcL(siteLp + vec2(0.0, -r));
cell = acc / 5.0;
}

// Per-shard shading from the site's own hash: breaks up large flat areas so two
// adjacent cells of the same source colour are still readable as two cells.
float hv = h21(sid * 2.17 + 9.1);
cell *= 1.0 + (hv - 0.5) * shade * 0.55;
cell = sat3(cell, saturate);

// ---- came / edge ---------------------------------------------------------
// F2 - F1 is zero exactly on the cell border and grows inside, so the came is
// drawn with smoothstep() and never prints a hard aliased step.
float border = max(sqrt(d2) - sqrt(d1), 0.0);
float lw = edgeW * 0.30;
float soft = 0.008 + edgeSoft * 0.055;
float edge = edgeW <= 0.0 ? 0.0 : 1.0 - smoothstep(lw, lw + soft, border);

vec3 base = src.rgb / max(src.a, 1e-4);
vec3 c = mix(base, cell, 1.0);
c = mix(c, edgeCol.rgb, sat(edge * 0.90 * edgeCol.a));

// Preserve the source's own detail by letting the source luminance modulate the
// flat fill - without this the result looks like paint-by-numbers.
float srcLum = lumOf(base);
c *= mix(1.0, 0.55 + 0.90 * srcLum, detail);

c = clamp(c, 0.0, 1.0);
c = mix(base, c, mixAmt);
float alpha = src.a * opacity;
gl_FragColor = vec4(c * alpha, alpha);
}

#define EPS 0.00001
#define PI 3.14159265359
float hash(float n) {
return fract(sin(n) * 43758.5453123);
}
float catmullRom(float t, float s) {
float i = floor(t);
float f = fract(t);
float a = hash(i - 1.0 + s);
float b = hash(i + s);
float c = hash(i + 1.0 + s);
float d = hash(i + 2.0 + s);
float f2 = f * f;
float f3 = f2 * f;
return (-0.5*a + 1.5*b - 1.5*c + 0.5*d) * f3
+ (a - 2.5*b + 2.0*c - 0.5*d) * f2
+ (-0.5*a + 0.5*c) * f
+ b;
}
float bandedNoise(float t, float s, float sm) {
float low = catmullRom(t * 0.7, s) * 2.0 - 1.0;
float mid = catmullRom(t * 2.1, s + 50.0) * 2.0 - 1.0;
float hi1 = catmullRom(t * 5.3, s + 100.0) * 2.0 - 1.0;
float hi2 = catmullRom(t * 11.7, s + 150.0) * 2.0 - 1.0;
float hiBlend = mix(hi1, hi2, 0.5) * mix(0.3, 0.15, sm);
return low * lowFreqAmp
+ mid * midFreqAmp * mix(0.5, 0.3, sm)
+ hiBlend * highFreqAmp;
}
float getRand(float time, float freq, float ph, float seedOff) {
float t = (time + ph) * freq;
float s = seed + seedOff;
return bandedNoise(t, s, smoothness);
}
float getWave(float time, float freq, float ph) {
return sin((time + ph) * freq * 2.0 * PI);
}
float getEnvelope(float time) {
float env = 1.0;
if (decayAmount > EPS) {
env *= mix(1.0, exp(-time * decaySpeed), decayAmount);
}
if (rampAmount > EPS) {
env *= mix(1.0, 1.0 - exp(-time * rampSpeed), rampAmount);
}
return clamp(env, 0.0, 1.0);
}
float applySpring(float value, float time, float seedOff) {
if (springTension < EPS) return value;
float omega = mix(5.0, 20.0, springTension);
float zeta = mix(0.1, 0.9, springDamping);
float mass = max(springMass, 0.1);
float dampedFreq = omega * sqrt(max(1.0 - zeta * zeta, EPS));
float springOsc = exp(-zeta * omega * time / mass) * sin(dampedFreq * time);
return value + value * springOsc * springTension * 0.5;
}
vec2 applyMode(vec2 offset, float time) {
float md = float(shakeMode);
float mi = modeIntensity;
if (md < 1.5) {
return offset;
}
if (md < 2.5) {
float driftX = catmullRom(time * 0.3, seed + 700.0) * 2.0 - 1.0;
float driftY = catmullRom(time * 0.25, seed + 710.0) * 2.0 - 1.0;
float microX = catmullRom(time * 8.0, seed + 720.0) * 2.0 - 1.0;
float microY = catmullRom(time * 7.5, seed + 730.0) * 2.0 - 1.0;
float breathX = sin(time * 0.8 * PI) * 0.08;
float breathY = cos(time * 0.6 * PI) * 0.06;
offset.x = offset.x * 0.5 + (driftX * 0.3 + microX * 0.08 + breathX) * mi * amplitude * 0.01;
offset.y = offset.y * 0.5 + (driftY * 0.3 + microY * 0.08 + breathY) * mi * amplitude * 0.01;
return offset;
}
if (md < 3.5) {
float rumbleX = catmullRom(time * 1.5, seed + 800.0) * 2.0 - 1.0;
float rumbleY = catmullRom(time * 1.3, seed + 810.0) * 2.0 - 1.0;
float spikeX = catmullRom(time * 12.0, seed + 820.0) * 2.0 - 1.0;
float spikeY = catmullRom(time * 11.0, seed + 830.0) * 2.0 - 1.0;
spikeX = spikeX * spikeX * sign(spikeX);
spikeY = spikeY * spikeY * sign(spikeY);
offset.x = offset.x * (1.0 + mi * 0.5) + (rumbleX * 0.4 + spikeX * 0.15) * mi * amplitude * 0.01;
offset.y = offset.y * (1.0 + mi * 0.5) + (rumbleY * 0.4 + spikeY * 0.15) * mi * amplitude * 0.01;
return offset;
}
if (md < 4.5) {
float whipBase = sin(time * frequency * PI * 2.0);
float whipSnap = pow(abs(whipBase), 3.0) * sign(whipBase);
float whipNoiseX = catmullRom(time * 6.0, seed + 900.0) * 2.0 - 1.0;
float whipNoiseY = catmullRom(time * 5.5, seed + 910.0) * 2.0 - 1.0;
float angle = globalAngle * PI / 180.0;
float whipX = whipSnap * cos(angle) + whipNoiseX * 0.2;
float whipY = whipSnap * sin(angle) + whipNoiseY * 0.2;
offset.x = whipX * mi * amplitude * 0.015;
offset.y = whipY * mi * amplitude * 0.015;
return offset;
}
if (md < 5.5) {
float bounceT = time * frequency * 1.5;
float bounceX = abs(sin(bounceT * PI)) * exp(-bounceT * 0.3);
float bounceY = abs(sin(bounceT * PI * 0.8 + 0.5)) * exp(-bounceT * 0.35);
float dirX = (mod(floor(bounceT), 2.0) == 0.0) ? 1.0 : -1.0;
float dirY = (mod(floor(bounceT * 0.8), 2.0) == 0.0) ? 1.0 : -1.0;
float bnX = catmullRom(time * 4.0, seed + 1000.0) * 2.0 - 1.0;
float bnY = catmullRom(time * 3.5, seed + 1010.0) * 2.0 - 1.0;
offset.x = (bounceX * dirX * mi + bnX * 0.1 * mi) * amplitude * 0.01;
offset.y = (bounceY * dirY * mi + bnY * 0.1 * mi) * amplitude * 0.01;
return offset;
}
if (md < 6.5) {
float jitX = hash(floor(time * frequency * 3.0) + seed + 1100.0) * 2.0 - 1.0;
float jitY = hash(floor(time * frequency * 2.8) + seed + 1110.0) * 2.0 - 1.0;
float smooth1 = catmullRom(time * 15.0, seed + 1120.0) * 2.0 - 1.0;
float smooth2 = catmullRom(time * 14.0, seed + 1130.0) * 2.0 - 1.0;
offset.x = mix(jitX, smooth1, smoothness) * mi * amplitude * 0.01;
offset.y = mix(jitY, smooth2, smoothness) * mi * amplitude * 0.01;
return offset;
}
if (md < 7.5) {
float d1 = catmullRom(time * 0.15, seed + 1200.0) * 2.0 - 1.0;
float d2 = catmullRom(time * 0.12, seed + 1210.0) * 2.0 - 1.0;
float d3 = catmullRom(time * 0.4, seed + 1220.0) * 2.0 - 1.0;
float d4 = catmullRom(time * 0.35, seed + 1230.0) * 2.0 - 1.0;
offset.x = (d1 * 0.7 + d3 * 0.3) * mi * amplitude * 0.01;
offset.y = (d2 * 0.7 + d4 * 0.3) * mi * amplitude * 0.01;
return offset;
}
if (md < 8.5) {
float punchDecay = exp(-time * 5.0 * mi);
float punchX = sin(time * frequency * PI * 4.0) * punchDecay;
float punchY = cos(time * frequency * PI * 3.0 + 0.5) * punchDecay;
float noiseX = catmullRom(time * 10.0, seed + 1300.0) * 2.0 - 1.0;
float noiseY = catmullRom(time * 9.0, seed + 1310.0) * 2.0 - 1.0;
offset.x = (punchX + noiseX * 0.15 * punchDecay) * mi * amplitude * 0.012;
offset.y = (punchY + noiseY * 0.15 * punchDecay) * mi * amplitude * 0.012;
return offset;
}
return offset;
}
vec2 applyEdge(vec2 uv, float mode) {
if (mode < 1.5) {
return uv;
} else if (mode < 2.5) {
return fract(uv);
} else {
vec2 r = uv;
r.x = (mod(floor(r.x), 2.0) == 0.0) ? fract(r.x) : 1.0 - fract(r.x);
r.y = (mod(floor(r.y), 2.0) == 0.0) ? fract(r.y) : 1.0 - fract(r.y);
return r;
}
}
void main() {
vec2 uv = acScreenNorm;
float t = acTime;
float em = float(edgeMode);
float env = getEnvelope(t);
float xOff = 0.0;
if (xRandAmp > EPS) {
xOff += getRand(t, frequency * xRandFreq, xPhase, 0.0) * xRandAmp;
}
if (xWaveAmp > EPS) {
xOff += getWave(t, xWaveFreq, xPhase) * xWaveAmp;
}
xOff *= amplitude * 0.01;
xOff += xBias * amplitude * 0.005;
float yOff = 0.0;
if (yRandAmp > EPS) {
yOff += getRand(t, frequency * yRandFreq, yPhase, 100.0) * yRandAmp;
}
if (yWaveAmp > EPS) {
yOff += getWave(t, yWaveFreq, yPhase) * yWaveAmp;
}
yOff *= amplitude * 0.01;
yOff += yBias * amplitude * 0.005;
vec2 offset = applyMode(vec2(xOff, yOff), t);
offset.x = applySpring(offset.x, t, 0.0);
offset.y = applySpring(offset.y, t, 50.0);
offset *= env;
float angRad = globalAngle * PI / 180.0;
float cosA = cos(angRad);
float sinA = sin(angRad);
float rX = offset.x * cosA - offset.y * sinA;
float rY = offset.x * sinA + offset.y * cosA;
offset = vec2(rX, rY);
vec2 shakenUV = uv + offset;
float outBounds = 1.0;
if (em < 1.5) {
outBounds = (shakenUV.x < 0.0 || shakenUV.x > 1.0 || shakenUV.y < 0.0 || shakenUV.y > 1.0) ? 0.0 : 1.0;
}
shakenUV = applyEdge(shakenUV, em);
shakenUV = clamp(shakenUV, 0.0, 1.0);
vec4 original = texture2DCv(inputImg.texture, uv);
vec4 shaken = texture2DCv(inputImg.texture, shakenUV);
vec3 fin = shaken.rgb * outBounds;
float finA = shaken.a * outBounds;
fin = mix(original.rgb, fin, globalMix);
finA = mix(original.a, finA, globalMix);
fin = clamp(fin, 0.0, 1.0);
gl_FragColor = vec4(fin, finA);
}

void main() {
float actualOffset = offset + 0.05;
vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
texColor.rgb *= stepCount;
texColor.rgb += actualOffset;
texColor.rgb = floor(texColor.rgb);
texColor.rgb -= actualOffset;
texColor.rgb /= stepCount;
gl_FragColor = texColor;
}

vec3 hueShift(vec3 col, float shift) {
vec3 P = vec3(0.55735) * dot(vec3(0.55735), col);
vec3 U = col - P;
vec3 V = cross(vec3(0.55735), U);
col = U * cos(shift * 6.2832) + V * sin(shift * 6.2832) + P;
return max(vec3(0.0), col);
}
float hash(float n) { return fract(sin(n) * 43758.5453123); }
vec3 lensFlare(vec2 uv, vec2 pos) {
vec2 main = uv - pos;
float dist = length(main);
float ang = atan(main.y, main.x);
vec3 f = vec3(0.0);
vec3 colCore = hueShift(vec3(1.0, 0.9, 0.8), flareHue);
vec3 colStreak = hueShift(vec3(0.8, 0.5, 0.2), flareHue);
vec3 colGhost = hueShift(vec3(0.9, 0.8, 1.0), flareHue);
int type = int(floor(flareType + 0.5));
float activeStreak = 0.0;
float activeStar = 0.0;
float activeGhosts = 0.0;
if (type == 0) {
activeStreak = 0.0;
activeStar = 0.0;
activeGhosts = 0.0;
} else if (type == 1) {
activeStreak = 1.0;
activeStar = 0.0;
activeGhosts = 0.2;
} else if (type == 2) {
activeStreak = 0.0;
activeStar = 1.0;
activeGhosts = 0.1;
} else {
activeStreak = 0.3;
activeStar = 0.2;
activeGhosts = 1.0;
}
float sStr = streakStr * activeStreak;
float stStr = starburstStr * activeStar;
float gStr = ghostStr * activeGhosts;
float core = 1.0 / (dist * (20.0 / glowSize) + 0.5);
core = pow(core, 2.0);
f += colCore * core * 2.0;
if (stStr > 0.01) {
float rays = abs(cos(ang * 3.0)) * 0.5 + abs(cos(ang * 12.0)) * 0.2;
rays += smoothstep(0.0, 1.0, abs(sin(ang * 100.0))) * 0.1;
rays *= 0.2 / (dist + 0.1);
f += colCore * rays * stStr;
}
if (sStr > 0.01) {
float vDist = abs(main.y);
float streak = exp(-vDist * 40.0);
streak *= smoothstep(1.5, 0.1, abs(main.x));
f += colStreak * streak * sStr;
}
if (gStr > 0.01) {
vec2 ghostVec = -pos * 0.5;
for (float i = 0.0; i < 5.0; i++) {
float t = fract(i * 0.35 + 0.3);
vec2 gPos = pos + ghostVec * (t * 4.0);
float size = 0.05 + 0.15 * hash(i * 12.3);
float chr = 0.02 * dist;
vec3 ghostCol = vec3(0.0);
float d = length(uv - gPos);
ghostCol.r = smoothstep(size + chr, size - 0.01 + chr, d);
ghostCol.g = smoothstep(size,       size - 0.01,       d);
ghostCol.b = smoothstep(size - chr, size - 0.01 - chr, d);
float hollow = smoothstep(0.0, size * 0.8, d);
ghostCol *= 0.5 + 0.5 * hollow;
float alpha = 0.1 * gStr * (1.0 - t * 0.5);
f += ghostCol * alpha * colGhost;
}
}
return f * intensity;
}
void main() {
vec2 uv = acScreenNorm;
vec2 aspectVec = vec2(acLayerSize.x / acLayerSize.y, 1.0);
vec2 cUV = (uv - 0.5) * aspectVec;
vec2 lightPos = (vec2(posX, 1.0 - posY) - 0.5) * aspectVec;
vec3 col = texture2DCv(inputImg.texture, uv).rgb;
vec3 flare = lensFlare(cUV, lightPos);
col += flare;
col = col * 0.8;
const float a = 2.51;
const float b = 0.03;
const float c = 2.43;
const float d = 0.59;
const float e = 0.14;
col = clamp((col*(a*col+b))/(col*(c*col+d)+e), 0.0, 1.0);
col = pow(col, vec3(1.0/2.2));
gl_FragColor = vec4(col, 1.0);
}

vec2 getResolution(){
vec2 s = inputImg.size;
if (s.x <= 0.0 || s.y <= 0.0) s = vec2(1920.0, 1080.0);
return s;
}
float gray(vec4 c){ return dot(c.rgb, vec3(0.299,0.587,0.114)); }
mat2 rot2(float a){ float c=cos(a), s=sin(a); return mat2(c,-s,s,c); }
float getLuma(vec2 uv) {
return gray(texture2DCv(inputImg.texture, uv));
}
float sobel(vec2 uv, vec2 pixel, float w) {
vec2 p = pixel * w;
float t00 = getLuma(uv + p * vec2(-1, -1));
float t10 = getLuma(uv + p * vec2( 0, -1));
float t20 = getLuma(uv + p * vec2( 1, -1));
float t01 = getLuma(uv + p * vec2(-1,  0));
float t21 = getLuma(uv + p * vec2( 1,  0));
float t02 = getLuma(uv + p * vec2(-1,  1));
float t12 = getLuma(uv + p * vec2( 0,  1));
float t22 = getLuma(uv + p * vec2( 1,  1));
float gx = t00 + 2.0 * t01 + t02 - (t20 + 2.0 * t21 + t22);
float gy = t00 + 2.0 * t10 + t20 - (t02 + 2.0 * t12 + t22);
return length(vec2(gx, gy));
}
void main(){
vec2 res = getResolution();
vec2 uv = acScreenNorm;
vec2 pixel = 1.0 / res;
float ang = radians(stripeDirDeg);
vec2 dir = rot2(ang) * vec2(1.0, 0.0);
float edge = sobel(uv, pixel, edgeWidth) * edgeAmt;
float maskEdge = clamp(edge, 0.0, 1.0);
if(edgeInvert) maskEdge = 1.0 - maskEdge;
vec4 s0 = texture2DCv(inputImg.texture, uv);
float amp = gray(s0);
float basePhase = phaseStart + acTime * phaseSpeed + offset;
float mag = stripeMag;
float wave = dot(uv - 0.5, dir) * mag + basePhase;
wave += edge * edgeWarp;
wave += amp * edgeWarp * 0.5;
float fBase = freqColors;
float rC = 0.5 + 0.5 * sin(wave * fBase * freqRed + phaseRed);
float gC = 0.5 + 0.5 * sin(wave * fBase * freqGreen + phaseGreen);
float bC = 0.5 + 0.5 * sin(wave * fBase * freqBlue + phaseBlue);
vec3 colS = vec3(rC, gC, bC);
vec3 tint = tintColor.rgb;
vec3 colT = colS * tint;
if(!edgeInvert) {
colT *= (1.0 - maskEdge * 0.8);
} else {
colT += maskEdge * 0.5;
}
float g = dot(colT, vec3(0.299,0.587,0.114));
vec3 colSat = mix(vec3(g), colT, clamp(saturation, 0.0, 2.0));
colSat *= brightness;
vec3 srcCol = s0.rgb;
float aIn = s0.a;
vec3 stripeBlend = mix(colSat, srcCol, mixWithSource);
vec3 outCol = mix(srcCol, stripeBlend, aIn);
gl_FragColor = vec4(outCol, aIn);
}

vec3 rgb2yuv(vec3 c) {
float y =  0.2126*c.r + 0.7152*c.g + 0.0722*c.b;
float u = -0.1146*c.r - 0.3854*c.g + 0.5000*c.b;
float v =  0.5000*c.r - 0.4542*c.g - 0.0458*c.b;
return vec3(y, u, v);
