float rand(vec2 co) {
return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
}
void main() {
vec4 texColor = texture2DCv(inputImg.texture, acScreenNorm);
vec2 st = acScreenNorm;
float t = seed + acTime * dissolveSpeed;
float r = rand(st * (1.0 + t * 0.1) + vec2(t * 1.33, t * 0.77));
float alpha = step(dissolvePercent, r);
gl_FragColor = texColor * alpha;
}

float hash(float n) {
return fract(sin(n * 12.9898 + seed * 78.233) * 43758.5453123);
}
float hash2(float n, float s) {
return fract(sin(n * 17.371 + s * 91.713 + seed * 41.17) * 24634.6345);
}
float smoothNoise(float x) {
float i = floor(x);
float f = fract(x);
float a = hash(i);
float b = hash(i + 1.0);
f = f * f * (3.0 - 2.0 * f);
return mix(a, b, f);
}
vec3 saturateColor(vec3 col, float sat) {
float grey = dot(col, vec3(0.2126, 0.7152, 0.0722));
return mix(vec3(grey), col, sat);
}
vec3 applyContrast(vec3 col, float con) {
return (col - 0.5) * con + 0.5;
}
float getFlicker(float t) {
float timeValue = t * frequency + phase * 100.0;
float steppedTime = floor(timeValue);
float mixedTime = mix(timeValue, steppedTime, frameBased);
float hardRand = hash(floor(timeValue));
float softRand = smoothNoise(timeValue);
float randValue = mix(hardRand, softRand, smoothRandom);
float pulseValue = sin(timeValue * 6.2831853) * 0.5 + 0.5;
float randomPulse = pulseValue * randValue;
float finalFlicker = randValue;
if (flickerMode == 0) {
finalFlicker = hash(floor(mixedTime));
}
else if (flickerMode == 1) {
finalFlicker = smoothNoise(timeValue);
}
else if (flickerMode == 2) {
finalFlicker = pulseValue;
}
else if (flickerMode == 3) {
finalFlicker = randomPulse;
}
finalFlicker = mix(finalFlicker, smoothNoise(timeValue), smoothRandom * 0.5);
return finalFlicker;
}
void main() {
vec2 uv = acScreenNorm;
float t = acTime;
vec4 src = texture2DCv(inputImg.texture, uv);
vec3 col = src.rgb;
float flicker = getFlicker(t);
float centered = (flicker - 0.5) * 2.0;
centered += bias;
centered = clamp(centered, -2.0, 2.0);
float brightnessMult = 1.0 + centered * brightnessAmp;
float strobePhase = fract((t * frequency) + phase);
float strobeMask = step(strobePhase, strobeWidth);
float strobeMult = mix(1.0, strobeMask * 2.0, strobeAmount);
brightnessMult *= strobeMult;
col *= baseBrightness;
col *= brightnessMult;
float rt = t * frequency + 13.1 + phase * 50.0;
float gt = t * frequency + 37.7 + phase * 80.0;
float bt = t * frequency + 91.3 + phase * 120.0;
float rNoise = mix(hash2(floor(rt), 1.0), smoothNoise(rt), smoothRandom);
float gNoise = mix(hash2(floor(gt), 2.0), smoothNoise(gt), smoothRandom);
float bNoise = mix(hash2(floor(bt), 3.0), smoothNoise(bt), smoothRandom);
float rFlick = 1.0 + ((rNoise - 0.5) * 2.0) * colorAmp * redAmount;
float gFlick = 1.0 + ((gNoise - 0.5) * 2.0) * colorAmp * greenAmount;
float bFlick = 1.0 + ((bNoise - 0.5) * 2.0) * colorAmp * blueAmount;
col *= vec3(rFlick, gFlick, bFlick);
col = applyContrast(col, contrast);
col = saturateColor(col, saturation);
col = clamp(col, 0.0, 1.0);
vec4 result = vec4(col, src.a);
gl_FragColor = mix(src, result, blend);
}

#define PI 3.14159265359
#define GOLDEN_ANGLE 2.3999632
float dither(vec2 uv) {
return fract(sin(dot(uv, vec2(12.9898, 78.233))) * 43758.5453) * 0.004;
}
void main() {
vec2 uv = acScreenNorm.xy;
float aspect = acScreenSize.x / acScreenSize.y;
vec4 source = texture2DCv(inputImg.texture, uv);
vec3 glowSum = vec3(0.0);
float totalWeight = 0.0;
int samples = int(quality);
vec3 colorWeights = vec3(1.0, 1.0 + dispersion * 0.4, 1.0 + dispersion * 1.2);
for(int i = 0; i < 64; i++) {
if (i >= samples) break;
float fraction = float(i) / float(samples);
float angle = float(i) * GOLDEN_ANGLE;
float dist = pow(fraction, 0.8);
vec2 dir = vec2(cos(angle), sin(angle));
vec2 scale = vec2(widthX, widthY) * glowWidth * 0.12;
scale.x /= aspect;
float weight = exp(-dist * dist * 5.0);
vec2 uvR = uv + dir * dist * scale * colorWeights.r;
vec2 uvG = uv + dir * dist * scale * colorWeights.g;
vec2 uvB = uv + dir * dist * scale * colorWeights.b;
float r = max(texture2DCv(inputImg.texture, uvR).r - threshold, 0.0);
float g = max(texture2DCv(inputImg.texture, uvG).g - threshold, 0.0);
float b = max(texture2DCv(inputImg.texture, uvB).b - threshold, 0.0);
glowSum += vec3(r, g, b) * weight;
totalWeight += weight;
}
vec3 finalGlow = (glowSum / totalWeight) * brightness;
finalGlow += dither(uv);
vec3 result = 1.0 - (1.0 - source.rgb) * (1.0 - finalGlow);
result = pow(max(result, 0.0), vec3(0.95));
vec4 finalColor = vec4(result, source.a);
gl_FragColor = mix(source, finalColor, blend);
}

#define PI 3.14159265359
float getLuma(vec3 rgb) {
return dot(rgb, vec3(0.2126, 0.7152, 0.0722));
}
vec3 auraPalette(float t) {
vec3 col = 0.5 + 0.5 * cos(6.28318 * (t + vec3(0.0, 0.33, 0.67)));
float bands = sin(t * 15.0);
col *= 0.8 + 0.4 * smoothstep(-0.2, 0.2, bands);
return col;
}
void main() {
vec2 luv = acLayerNorm.xy;
vec2 suv = acScreenNorm.xy;
vec2 uv;
vec2 aspect;
if(followLayer) {
uv = luv;
aspect = vec2(acLayerSize.x / acLayerSize.y, 1.0);
} else {
uv = suv;
aspect = vec2(acScreenSize.x / acScreenSize.y, 1.0);
}
vec2 p = (uv - 0.5) * aspect;
vec4 source = texture2DCv(inputImg.texture, uv);
float dist = 0.0;
const int SAMPLES = 16;
for(int i = 0; i < SAMPLES; i++) {
float sampleAngle = float(i) * (2.0 * PI / float(SAMPLES));
vec2 sampleDir = vec2(cos(sampleAngle), sin(sampleAngle));
vec2 offset = sampleDir * glowWidth * 0.1;
offset.x /= aspect.x;
vec2 sampleUV = uv + offset;
float sampleLuma = getLuma(texture2DCv(inputImg.texture, sampleUV).rgb);
dist += smoothstep(threshold, 1.0, sampleLuma);
}
dist /= float(SAMPLES);
float angle = atan(p.y, p.x);
float timePhase = acTime * phaseSpeed;
float auraMap = dist * frequency + (angle / PI) * twist + timePhase;
const vec3 phaseRGB = vec3(0.2, 0.1, 0.0);
vec3 auraCol = vec3(
auraPalette(auraMap + phaseRGB.r).r,
auraPalette(auraMap + phaseRGB.g).g,
auraPalette(auraMap + phaseRGB.b).b
);
float mask = smoothstep(0.0, 0.5, dist) * (1.0 - smoothstep(0.5, 1.2, dist));
auraCol *= mask * brightness;
vec3 result = 1.0 - (1.0 - source.rgb) * (1.0 - auraCol);
if(getLuma(source.rgb) > 0.8) result = source.rgb;
vec4 finalColor = vec4(result, source.a);
gl_FragColor = mix(source, finalColor, blend);
}

const int MAXSTEPS = 64;
const float PI = 3.14159265359;

float getVal(vec3 col, int type){
if (type == 1) return col.r;
if (type == 2) return col.g;
if (type == 3) return col.b;
return dot(col, vec3(0.2126, 0.7152, 0.0722));
}
float hash21(vec2 p){ return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }

float gAsp = 1.0;   // layer aspect - set once in main()

// LAYER -> SCREEN. The run marches in layer space so the streaks rotate and
// scale with the layer; every read of the source has to come back through here.
vec2 lpToScreen(vec2 v){ return (vec4(v, 0.0, 1.0) * acLayerToScreen).xy; }
vec4 fetchA(vec2 a){ return texture2DCv(inputImg.texture, clamp(lpToScreen(vec2(a.x / gAsp, a.y)), 0.0, 1.0)); }

void main(){
vec4 src = texture2DCv(inputImg.texture, acScreenNorm);
vec2 lp  = acLayerNorm;

// Aspect-corrected layer space: isotropic, so the sort angle means the same
// thing visually whatever shape the layer is.
gAsp = acLayerSize.x / max(acLayerSize.y, 1.0);
vec2 lpA = vec2(lp.x * gAsp, lp.y);

float rad = sortAngle * (PI / 180.0);
vec2 dirA = vec2(cos(rad), sin(rad));

int   ty   = int(sortType);
float soft = max(softenThreshold, 0.001);
float tLow  = threshold - soft * 0.5;
float tHigh = threshold + soft * 0.5;

float val  = getVal(src.rgb, ty);
float inRun = ((abs(sortDirection - 0.0) < 0.5))
? smoothstep(tLow, tHigh, val)
: 1.0 - smoothstep(tLow, tHigh, val);

vec3 res = src.rgb;
if (inRun > 0.01){
// Per-pixel run length: with Randomly Restart the streaks break into
// segments instead of running off the edge of the layer.
float rnd = hash21(vec2(seed, seed * 0.5) + floor(lpA * 24.0) * 0.017);
float runLen = streak * mix(1.0, 0.25 + 0.75 * rnd, randomlyRestart);
float stepLen = max(runLen, 1e-4) / float(max(steps, 1.0));

int stepsI = int(clamp(steps, 8.0, 64.0));
float bestVal = ((abs(sortDirection - 0.0) < 0.5)) ? -1.0 : 2.0;
vec3  bestCol = src.rgb;
vec3  acc = src.rgb;
float wsum = 1.0;
float count = 1.0;

for (int i = 1; i < MAXSTEPS; i++){
if (i >= stepsI) break;
float d = float(i) * stepLen;
vec2 sA = lpA - dirA * d;
// outside the layer -> the run ended
if (sA.x < 0.0 || sA.x > gAsp || sA.y < 0.0 || sA.y > 1.0) break;
vec4 sc = fetchA(sA);
float sv = getVal(sc.rgb, ty);
float sm = ((abs(sortDirection - 0.0) < 0.5))
? smoothstep(tLow, tHigh, sv)
: 1.0 - smoothstep(tLow, tHigh, sv);
// the pixel that fails the threshold test ends the run - this is what
// makes it a SORT and not a directional blur
if (sm < 0.5) break;
if ((abs(sortDirection - 0.0) < 0.5)){ if (sv > bestVal){ bestVal = sv; bestCol = sc.rgb; } }
else                   { if (sv < bestVal){ bestVal = sv; bestCol = sc.rgb; } }
acc += sc.rgb;
wsum += 1.0;
count += 1.0;
}

vec3 runCol = ((abs(sortMode - 0.0) < 0.5)) ? bestCol : (acc / max(count, 1.0));
res = runCol;
}

res = clamp(res, 0.0, 1.0);
res = mix(res, src.rgb, mixWithSource);
gl_FragColor = vec4(res, src.a * opacity);
}

float gAsp = 1.0;

float gray(vec3 c){ return dot(c, vec3(0.299, 0.587, 0.114)); }
float satv(float x){ return clamp(x, 0.0, 1.0); }
vec3  satv(vec3 c){ return clamp(c, 0.0, 1.0); }

// LAYER -> SCREEN. The blob field is generated in layer space and the luma it
// is driven by is read from the layer's own pixels, so the pattern is printed on
// the layer and travels with it instead of sitting on the screen.
// Positions are anchored on acScreenNorm - the engine's own screen position for
// this fragment - so the anchor never depends on the matrix. Only the DELTA goes
// through acLayerToScreen, and the w=0 multiply cancels the translation, so a
// layer-space offset becomes a screen-space offset exactly. fetchL(acLayerNorm)
// therefore returns texture2DCv(inputImg.texture, acScreenNorm), the engine idiom.
vec2 lpToScreen(vec2 v){ return acScreenNorm + (vec4(v - acLayerNorm, 0.0, 0.0) * acLayerToScreen).xy; }
vec4 fetchL(vec2 lp){ return texture2DCv(inputImg.texture, clamp(lpToScreen(lp), 0.0, 1.0)); }

// PREMULTIPLIED in: the luma that drives the bands must be straight colour. On
// premultiplied pixels every soft edge of the layer reads as black and gets
// pushed to the bottom of the ramp, which is what made this effect look broken.
vec3 colL(vec2 lp){
vec4 s = fetchL(lp);
return s.rgb / max(s.a, 1e-4);
}

float hash(vec2 p){
return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453123);
}
float smoothNoise(vec2 p){
vec2 i = floor(p);
vec2 f = fract(p);
f = f * f * (3.0 - 2.0 * f);
float bottom = mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x);
float top = mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x);
return mix(bottom, top, f.y);
}
float fbm(vec2 p){
float v = 0.0;
float a = 0.5;
vec2 shift = vec2(100.0);
for (int i = 0; i < 6; i++){
if (float(i) >= float(blobOctaves)) break;
v += a * smoothNoise(p);
p = p * 2.0 + shift;
a *= 0.5;
}
return v;
}

void main(){
vec2 lp = acLayerNorm;
gAsp = acLayerSize.x / max(acLayerSize.y, 1.0);
vec4 srcSample = fetchL(lp);
float sA = srcSample.a;
vec3 srcRGB = srcSample.rgb / max(sA, 1e-4);
float srcLuma = gray(srcRGB);

// The field is generated in aspect-corrected layer space so the blobs stay round
// whatever shape the layer is.
vec2 noiseUV = vec2(lp.x * gAsp, lp.y) * noiseFreq;

// Domain warp: displacing the coordinate by another fbm before evaluating it is
// what turns round blobs into the folded, lava-lamp shapes the effect is named
// for. Cheap, and it is the difference between this and plain noise contours.
if (warp > 0.001){
vec2 w = vec2(fbm(noiseUV * 0.7 + vec2(3.1, 1.7)),
              fbm(noiseUV * 0.7 + vec2(9.2, 5.3)));
noiseUV += (w - vec2(0.5)) * warp * 2.0;
}

float blobs = fbm(noiseUV);
float combinedVal = (srcLuma * sourceScale) + blobs;

// The time term is wrapped with fract() before it reaches sin(). Left
// unbounded it grows with acTime until the argument exceeds what the driver's
// precision can resolve, at which point sin() returns garbage and the whole
// effect freezes into flat bands - that was the original bug. Wrapping it also
// makes the animation loop seamlessly.
float ph = fract(acTime * phaseSpeed * 0.2);
vec3 freqRGB = vec3(1.0, 1.15, 1.3);
vec3 phaseRGB = vec3(0.0, 0.33, 0.67);
vec3 colorPhase = (combinedVal * freqColors * freqRGB) + phaseRGB + ph;
vec3 outCol = 0.5 + 0.5 * sin(colorPhase * 6.283185);

// ---- contour lines --------------------------------------------------------
// Drawn where the band value crosses an integer: these are the iridescent rings
// the effect is supposed to have, and they were missing entirely before.
if (contour > 0.001){
vec3 cf = fract(combinedVal * freqColors * freqRGB);
vec3 cd = min(cf, 1.0 - cf);
float c = 1.0 - smoothstep(0.0, 0.06 + (1.0 - contour) * 0.3, min(min(cd.x, cd.y), cd.z));
outCol = mix(outCol, vec3(1.0) - outCol, c * contour);
}

float lumaOut = gray(outCol);
outCol = mix(vec3(lumaOut), outCol, saturation);
outCol *= brightness;

float outlineMask = smoothstep(0.05, 0.3 * max(outlineStrength, 0.001), srcLuma);
outCol *= mix(1.0, outlineMask, satv(outlineStrength));

vec3 finalCol = mix(outCol, srcRGB, satv(mixWithSource));
finalCol = satv(finalCol);
// Back to premultiplied on the way out.
gl_FragColor = vec4(finalCol * sA, sA * opacity);
}

const float SmallDetailSize = 0.1;
float getLuma(vec3 rgb) {
return dot(rgb, vec3(0.299, 0.587, 0.114));
}
vec3 blur(vec2 uv, float radius) {
vec2 res = acScreenSize;
vec3 col = vec3(0.0);
float total = 0.0;
for(float x = -2.0; x <= 2.0; x++) {
for(float y = -2.0; y <= 2.0; y++) {
float weight = exp(-(x*x + y*y) / (2.0 * radius * radius + 0.0001));
col += texture2DCv(inputImg.texture, uv + vec2(x, y) / res * radius).rgb * weight;
total += weight;
}
}
return col / total;
}
void main() {
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
vec3 source = src.rgb;
float baseR = sharpenWidth * 100.0;
float rTiny   = SmallDetailSize * 0.5 * baseR;
float rSmall  = SmallDetailSize * 1.0 * baseR;
float rMedium = SmallDetailSize * 2.0 * baseR;
float rLarge  = SmallDetailSize * 4.0 * baseR;
vec3 blurT = blur(uv, rTiny);
vec3 blurS = blur(uv, rSmall);
vec3 blurM = blur(uv, rMedium);
vec3 blurL = blur(uv, rLarge);
vec3 tinyFreq   = source - blurT;
vec3 smallFreq  = blurT - blurS;
vec3 mediumFreq = blurS - blurM;
vec3 largeFreq  = blurM - blurL;
vec3 details = (tinyFreq   * scaleTiny) +
(smallFreq  * scaleSmall) +
(mediumFreq * scaleMedium) +
(largeFreq  * scaleLarge);
details *= sharpenAmp;
float diffLuma = getLuma(abs(details));
float edgeMask = smoothstep(edgeThreshold + 0.1, edgeThreshold, diffLuma);
details *= edgeMask;
float sourceLuma = getLuma(source);
vec3 sourceChroma = source - sourceLuma;
float detailLuma = getLuma(details);
vec3 detailChroma = details - detailLuma;
vec3 resLuma   = vec3(sourceLuma + (detailLuma * sharpenLuma));
vec3 resChroma = sourceChroma + (detailChroma * sharpenChroma);
vec3 finalRGB = resLuma + resChroma;
finalRGB.r = mix(source.r, finalRGB.r, sharpenR);
finalRGB.g = mix(source.g, finalRGB.g, sharpenG);
finalRGB.b = mix(source.b, finalRGB.b, sharpenB);
gl_FragColor = vec4(finalRGB, src.a);
}

#define PI 3.14159265359
vec2 rotate(vec2 v, float angle) {
float s = sin(angle);
float c = cos(angle);
return vec2(v.x * c - v.y * s, v.x * s + v.y * c);
}
vec2 applyWrap(vec2 uv, int mode) {
if (mode == 1) return fract(uv);
if (mode == 2) return abs(mod(uv - 1.0, 2.0) - 1.0);
return uv;
}
void main() {
vec2 luv = acLayerNorm.xy;
vec2 suv = acScreenNorm.xy;
vec2 uv;
vec2 aspect;
if(followLayer) {
uv = luv;
aspect = vec2(acLayerSize.x / acLayerSize.y, 1.0);
} else {
uv = suv;
aspect = vec2(acScreenSize.x / acScreenSize.y, 1.0);
}
vec2 p = uv - center;
p.x *= aspect.x;
float rad = lensRotate * (PI / 180.0);
p = rotate(p, rad);
p.x /= max(0.01, lensRelWidth);
p.y /= max(0.01, lensRelHeight);
float d = length(p);
float edgeSize = lensRadius * lensEdgeWidth;
float magFactor = 1.0;
if (d < lensRadius) {
magFactor = magnifyAmount;
}
else if (d < lensRadius + edgeSize) {
float t = (d - lensRadius) / edgeSize;
float curve = mix(t, smoothstep(0.0, 1.0, t), lensEdgeShape);
magFactor = mix(magnifyAmount, 1.0, curve);
}
vec2 warpedP = p;
warpedP /= (magFactor * magnifyRel);
warpedP.x *= lensRelWidth;
warpedP.y *= lensRelHeight;
warpedP = rotate(warpedP, -rad);
warpedP.x /= aspect.x;
vec2 finalUV = center + warpedP;
finalUV = applyWrap(finalUV, int(wrapMode));
vec4 color = texture2DCv(inputImg.texture, finalUV);
if (d > lensRadius && d < lensRadius + edgeSize) {
color.rgb *= mix(0.95, 1.0, (d - lensRadius) / edgeSize);
}
vec4 base = texture2DCv(inputImg.texture, suv);
gl_FragColor = mix(base, color, blend);
}

#define PI 3.14159265359
float getLuma(vec3 color) {
return dot(color, vec3(0.299, 0.587, 0.114));
}
float getSmoothLuma(AC_ImageInfo img, vec2 uv, float smoothVal) {
float luma = 0.0;
float samples = 0.0;
float blurRadius = smoothVal * 0.01;
for(float x = -1.0; x <= 1.0; x++) {
for(float y = -1.0; y <= 1.0; y++) {
vec2 offset = vec2(x, y) * blurRadius;
luma += getLuma(texture2DCv(img.texture, uv + offset).rgb);
samples++;
}
}
return luma / samples;
}
vec2 applyWrap(vec2 uv, int mode) {
if (mode == 1) return fract(uv);
if (mode == 2) return abs(mod(uv - 1.0, 2.0) - 1.0);
return uv;
}
vec2 rotate(vec2 v, float a) {
float s = sin(a), c = cos(a);
return vec2(v.x * c - v.y * s, v.x * s + v.y * c);
}
void main() {
vec2 luv = acLayerNorm.xy;
vec2 suv = acScreenNorm.xy;
vec2 uv;
vec2 aspect;
if(followLayer) {
uv = luv;
aspect = vec2(acLayerSize.x / acLayerSize.y, 1.0);
} else {
uv = suv;
aspect = vec2(acScreenSize.x / acScreenSize.y, 1.0);
}
float delta = 0.005;
float l  = getSmoothLuma(inputImg, uv, smoothness);
float lx = getSmoothLuma(inputImg, uv + vec2(delta, 0.0), smoothness);
float ly = getSmoothLuma(inputImg, uv + vec2(0.0, delta), smoothness);
vec2 gradient = vec2(lx - l, ly - l);
gradient.x *= aspect.x;
if (rotateWarpDir != 0.0) {
gradient = rotate(gradient, rotateWarpDir * (PI / 180.0));
}
float dirMult = puff ? -1.0 : 1.0;
vec2 displacement = gradient * amount * dirMult;
displacement.x /= aspect.x;
vec2 warpedUV = uv + displacement;
warpedUV = applyWrap(warpedUV, int(wrapMode));
vec4 color = texture2DCv(inputImg.texture, warpedUV);
vec4 base = texture2DCv(inputImg.texture, suv);
gl_FragColor = mix(base, color, blend);
}

#define PI 3.14159265359
vec2 applyWrap(vec2 uv, int mode) {
if (mode == 1) return fract(uv);
if (mode == 2) return abs(mod(uv - 1.0, 2.0) - 1.0);
return uv;
}
vec2 getWaveOffset(vec2 p, float amp, float freq, float angle, float dispAngle, float pStart, float pSpeed, float time, float aspect) {
float rad = angle * (PI / 180.0);
float dispRad = dispAngle * (PI / 180.0);
vec2 waveDir = vec2(cos(rad), sin(rad));
vec2 dispDir = vec2(cos(rad + dispRad), sin(rad + dispRad));
vec2 pCorrected = p;
pCorrected.x *= aspect;
float phase = dot(pCorrected, waveDir) * freq + pStart + time * pSpeed;
return dispDir * sin(phase) * amp;
}
void main() {
vec2 luv = acLayerNorm.xy;
vec2 suv = acScreenNorm.xy;
vec2 uv;
vec2 aspect;
if(followLayer) {
uv = luv;
aspect = vec2(acLayerSize.x / acLayerSize.y, 1.0);
} else {
uv = suv;
aspect = vec2(acScreenSize.x / acScreenSize.y, 1.0);
}
vec2 p = (uv - 0.5) * zDist + 0.5;
vec2 offsetA = getWaveOffset(p, aAmplitude, aFrequency, aAngle, aDisplaceAngle, aPhaseStart, aPhaseSpeed, acTime, aspect.x);
vec2 offsetB = getWaveOffset(p, bAmplitude, bFrequency, bAngle, bDisplaceAngle, bPhaseStart, bPhaseSpeed, acTime, aspect.x);
vec2 totalOffset = offsetA + offsetB;
totalOffset.x /= aspect.x;
vec2 warpedUV = p + totalOffset;
warpedUV = applyWrap(warpedUV, int(wrapMode));
vec4 color = texture2DCv(inputImg.texture, warpedUV);
vec4 base = texture2DCv(inputImg.texture, suv);
gl_FragColor = mix(base, color, blend);
}

float hash(vec2 p) {
return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}
void main() {
vec2 uv = acScreenNorm;
float ang = radians(angle);
vec2 dir = vec2(cos(ang), sin(ang));
float freq = pixelFrequency / (1.0 + chunky * 4.0);
vec2 cells = vec2(freq / max(pixelRelWidth, 0.001), freq);
vec2 block = floor(uv * cells);
vec2 blockCenter = (block + 0.5) / cells;
float rnd = hash(block + vec2(seed * 1000.0));
float coord = dot(blockCenter - 0.5, dir) + 0.5;
float ew = max(edgeWidth, 0.0001);
float threshold = coord + (rnd - 0.5) * ew;
float wiped = step(threshold, wipePercent);
float reveal;
if (transitionDir == 0) {
reveal = 1.0 - wiped;
} else {
reveal = wiped;
}
if (showWipe > 0.5) {
gl_FragColor = vec4(vec3(reveal), 1.0);
return;
}
vec4 src = texture2DCv(inputImg.texture, uv);
vec4 bg;
if (background == 1) {
bg = vec4(0.0, 0.0, 0.0, 1.0);
} else {
bg = vec4(0.0, 0.0, 0.0, 0.0);
}
vec4 outCol = mix(bg, src, reveal);
gl_FragColor = outCol;
}

float hash12(vec2 p) {
return fract(sin(dot(p, vec2(12.9898,78.233))) * 43758.5453);
}
void main() {
vec2 res = acScreenSize;
vec2 uv  = acScreenNorm;
float ang = radians(scanAngle);
vec2 dir = vec2(cos(ang), sin(ang));
float scanCoord = dot(uv * res, dir);
float scanline = sin((scanCoord - progress * scrollSpeed) / max(scanlineHeight, 1.0));
vec3 vhsColor = scanColor.rgb * scanline * scanlineIntensity;
vec2 grainSeed = vec2(12.9898, 78.233) + progress * grainTimeScale;
float grain = fract(sin(dot((uv * res) * uv, grainSeed)) * 43758.5453);
vhsColor += vec3(grain) * grainIntensity;
vec2 tuv = uv;
if (glitchPhase < glitchProbability) {
float gx = (fract(sin(progress * 12.9898) * 43758.5453) - 0.5) * glitchIntensityX;
float gy = (fract(cos(progress * 78.233) * 43758.5453) - 0.5) * glitchIntensityY;
tuv += vec2(gx, gy);
}
float bandNoise = hash12(uv * res);
vec3 chromaColor = texture2DCv(inputImg.texture, tuv).rgb;
if (abs(uv.y - bandPos) < bandHeight) {
float rs = bandNoise * bandChoppiness;
vhsColor += vec3(rs) * staticAmount;
tuv.x += sin(uv.y * res.y * 10.0 + rs) * warpFactor;
chromaColor = vec3(
texture2DCv(inputImg.texture, tuv + vec2(chromaAmount * rs, 0.0)).r,
texture2DCv(inputImg.texture, tuv).g,
texture2DCv(inputImg.texture, tuv - vec2(chromaAmount * rs, 0.0)).b
);
vhsColor = mix(vhsColor, chromaColor, bandIntensity * (1.0 - rs));
}
vec3 originalColor = texture2DCv(inputImg.texture, tuv).rgb;
gl_FragColor = vec4(mix(originalColor, vhsColor, blendFactor), 1.0);
}

void main() {
int from = -max(1,int(radius));
int to = max(1,int(radius));
vec2 imgSize = inputImg.size;
float px = (1.0/imgSize.x);
float py = (1.0/imgSize.y);
if( acPass==0 ) {
float nearestOutside = radius * 2.0;
for(int i=from; i<to; i++ ) {
vec4 inColor = texture2DCv(inputImg.texture,vec2(acScreenNorm.s + float(i)*px + sdx*px,acScreenNorm.t));
float xdistOut = inColor.a > 0.0 ? abs(float(i)) : radius*2.0;
nearestOutside = min(nearestOutside,xdistOut);
}
gl_FragColor = vec4(nearestOutside/radius, 0.0, 0.0, 1.0);
} else {
float tOut = 2.0;
for(int i=from; i<to; i++ ) {
vec4 inColor = texture2DCv(hdist.texture,vec2(acScreenNorm.s,acScreenNorm.t + float(i)*py + sdy*py));
float xdistOut = inColor.r;
float ydist = abs(float(i))/radius;
float distOut = length(vec2(xdistOut,ydist));
tOut = min(tOut,distOut);
}
vec4 original = texture2DCv(inputImg.texture,acScreenNorm.st);
vec4 outColor = mix(vec4(0.0,0.0,0.0,0.5), vec4(0.0), smoothstep(0.0,1.0,tOut));
vec4 result = outColor;
result = original + result*(1.0-original.a);
gl_FragColor = result;
}
}

float rand2(vec2 co){
return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
}
float rand3 (vec3 v) {
return fract(sin(dot(v,vec3(12.9898,78.233,193.71)))*43758.5453123);
}
float rand4 (vec4 v) {
return fract(sin(dot(v,vec4(12.9898,78.233,193.71,397.318)))*43758.5453123);
}
vec2 randVec2(vec3 v) {
return vec2( rand4(vec4(v,5.124)), rand4(vec4(v,3.0)));
}
vec3 randVec3(vec3 v) {
return vec3( rand4(vec4(v,5.124)), rand4(vec4(v,7.23464)), rand4(vec4(v,3.0)));
}
vec2 l2s( vec2 v ) {
return (vec4(v,0.,1.)*acLayerToScreen).xy;
}
mat2 rot(float a) {
float c = cos(a);
float s = sin(a);
return mat2(
c, -s,
s, c
);
}
vec3 hsv2rgb(vec3 c)
{
vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}
vec3 rgb2hsv(vec3 c)
{
vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));
float d = q.x - min(q.w, q.y);
float e = 1.0e-10;
return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}
vec4 mixColors(vec4 a, vec4 b, float t) {
vec4 result;
if( interpHue ) {
result = vec4(hsv2rgb(mix(rgb2hsv(a.rgb),rgb2hsv(b.rgb),t)),mix(a.a,b.a,t));
} else {
result = mix(a,b,t);
}
return result;
}
vec4 getColor(vec3 id, float layerDepth) {
vec4 result;
if( coloring==0 ) {
result = vec4(0.);
} else if( coloring==1 ) {
result = color1;
} else if( coloring==2 ) {
result = color1 * rand4(vec4(id,0.1974));
} else if( coloring==3 ) {
result = mixColors(color1,color2,rand4(vec4(id,0.1974)));
} else if( coloring==4 ) {
vec2 rr = randVec2(id);
result = mixColors(mixColors(color1,color2,rr.x),color3,rr.y);
} else if( coloring==5 ) {
result = color1 * layerDepth;
} else if( coloring==6 ) {
result = mixColors(color1,color2,layerDepth);
} else if( coloring==7 ) {
result = layerDepth < 0.5 ? mixColors(color1,color2,layerDepth*2.) : mixColors(color2,color3,(layerDepth-0.5)*2.);
} else if( coloring==8 ) {
result = mixColors(color3,mixColors(color1,color2,rand4(vec4(id,0.1974))),layerDepth);
} else {
result = vec4(0.);
}
return result;
}
vec4 shapeGrid(vec2 st, float layer, float layerDepth) {
st *= 10.;
vec2 uv = fract(st);
vec3 id = vec3(floor(st),layer);
float size = sizeVariance < 0.0001 ? shapeSize : min(shapeSize, shapeSize * (1.+((rand4(vec4(id,0.351))-0.5)*sizeVariance)));
float angle = angleVariance < 0.0001 ? 0. : ((rand4(vec4(id,0.2793))-0.5)*angleVariance*12.56636);
float rr = rand3(id);
size *= smoothstep(rr,rr+0.008,density);
if( size < 0.00001 ) return vec4(0.);
uv -= 0.5;
uv *= acLayerSize.x > acLayerSize.y ? vec2(1.,acLayerSize.x/acLayerSize.y) : vec2(acLayerSize.y/acLayerSize.x,1.);
uv /= size;
float maxDisplace = (1./size - 1.);
vec2 displace;
if( abs(evolution) > 0.001 ) {
displace = mix(randVec2(id+floor(evolution)),randVec2(id+floor(evolution+1.)),fract(evolution));
} else {
displace = randVec2(id);
}
uv += clamp((displace-0.5)*max(1.0,maxDisplace)*slack,-maxDisplace,maxDisplace);
uv *= rot(angle + (shapeAngle * 0.0174532925));
uv += 0.5;
uv.y = 1. - uv.y;
vec4 texColor = texture2DCv(inputImg.texture,l2s(uv));
vec4 blendColor = getColor(id,layerDepth);
vec4 result;
if(lockLuminance || lockSaturation) {
vec3 texHsv = rgb2hsv(texColor.a <= 0.0 ? vec3(0.) : (texColor.rgb/texColor.a));
vec3 blendHsv = rgb2hsv(blendColor.a <= 0.0 ? vec3(0.) : (blendColor.rgb/blendColor.a));
if( lockLuminance ) blendHsv.z = texHsv.z;
if( lockSaturation ) blendHsv.y = texHsv.y;
result = vec4(hsv2rgb(mix(texHsv, blendHsv, blendColor.a)),1.) * texColor.a;
} else {
result = vec4(mix(texColor.a <= 0.0 ? vec3(0.) : (texColor.rgb/texColor.a), blendColor.a <= 0.0 ? vec3(0.) : (blendColor.rgb/blendColor.a), blendColor.a),1.) * texColor.a;
}
return result;
}
void main() {
vec2 st = acLayerNorm;
st.y = 1. - st.y;
st -= 0.5;
st.x *= acLayerSize.x/acLayerSize.y;
st /= scale*6.;
vec2 parallax = (pos.xy / 1000.) + 25.35;
float depth = pos.z / 100.;
vec4 result = vec4(0.);
float f = fract(depth);
float layer = floor(depth);
float filteredSeed = seed/5.0;
for( float i=layerCount-1.; i>=0.; i -= 1. ) {
vec2 uv = st;
uv *= ((1.+i)-f)/9.;
uv += parallax;
float layerDepth = smoothstep(layerCount,layerCount*(0.9999-fade),(i+1.)-f);
vec4 color = shapeGrid(uv, layer+i+filteredSeed, layerDepth)*alpha*layerDepth;
if( blendMode==1 ) {
vec3 fg = color.a<0.0001 ? vec3(0.) : color.rgb/color.a;
vec3 bg = result.a<0.0001 ? vec3(1.) : result.rgb/result.a;
result = result * (1.-color.a) + vec4(fg*bg,1.0)*color.a;
