float t = temperature / 100.0;
float tn = tint / 100.0;
float warm = t * 0.08;
rgb.r += warm;
rgb.b -= warm;
rgb.g += warm * 0.15;
rgb.g += tn * 0.08;
rgb.r -= tn * 0.03;
