float rand21(vec2 c){ return fract(sin(dot(c, vec2(12.9898,78.233))) * 43758.5453); }
void main(){
vec2 R = acScreenSize;
vec2 frag = acScreenNorm * R;
vec2 p = (2.0 * frag - R) / min(R.x, R.y) * UV_SCALE;
float z0 = acTime * SPEED;
float i = floor(z0);
float offs = fract(z0);
float shadow = 1.0;
vec3 outc = vec3(0.0);
int maxSteps = int(clamp(STEPS, 1.0, 300.0));
const int MAX_IT = 300;
for (int zi = 1; zi < MAX_IT; zi++){
if (zi >= maxSteps) break;
float z = float(zi);
float z2 = z - offs;
float randz = z + i;
float dadt = (rand21(vec2(randz, 1.0)) * 2.0 - 1.0) * 0.5;
float a = rand21(vec2(randz, 1.0)) * 2.0 * 3.14159265 + dadt * acTime;
float pullback = rand21(vec2(randz, 3.0)) * PULL_ADD + PULL_MIN;
float r = rand21(vec2(randz, 4.0)) * R_ADD + R_MIN;
float g = rand21(vec2(randz, 5.0)) * G_ADD + G_MIN;
float b = rand21(vec2(randz, 6.0)) * B_ADD + B_MIN;
vec2 origin = vec2(sin(randz*0.005)+sin(randz*0.002), cos(randz*0.005)+cos(randz*0.002)) * z2 * 0.002;
vec2 dir = vec2(cos(a), sin(a));
float dist = dot(dir, p - origin) * z2;
float xdist = dot(vec2(-dir.y, dir.x), p - origin) * z2;
float wobble = dist - pullback + sin(xdist * WOBBLE_FREQ) * WOBBLE_AMP;
if (wobble > 0.0){
float dotsize = rand21(vec2(randz, 7.0)) * DOT_ADD + DOT_MIN;
float patternsize = rand21(vec2(randz, 8.0)) * PAT_ADD + PAT_MIN;
float pattern = step(dotsize, length(fract(vec2(dist, xdist) * patternsize) - 0.5)) * PAT_GAIN + PAT_BASE;
float bright = 1.0;
if (wobble < THRESH_1) bright = BRIGHT_1;
else if (wobble < THRESH_2) bright = BRIGHT_2;
else bright = pattern;
vec3 col = vec3(r, g, b);
vec3 cacc = GAIN * col * shadow / (z2 + DENOM_BIAS) * bright;
outc = cacc;
outc = pow(max(outc, 0.0), vec3(GAMMA));
gl_FragColor = vec4(outc, 1.0);
return;
} else {
shadow *= 1.0 - exp((dist - pullback) * SHADOW_DECAY) * SHADOW_GAIN;
}
}
gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0);
}

void main(){
vec2 uv = acScreenNorm;
vec2 texel = 1.0 / inputImg.size;
vec3 centerColor = texture2DCv(inputImg.texture, uv).rgb;
vec3 accum = vec3(0.0);
float wsum = 0.0;
for(int j=-2;j<=2;j++){
for(int i=-2;i<=2;i++){
vec2 off = vec2(float(i), float(j));
vec3 nc = texture2DCv(inputImg.texture, uv + off * texel).rgb;
float spatial = exp(-(off.x*off.x + off.y*off.y) / 8.0);
float cd = length(centerColor - nc);
float range = exp(-(cd*cd) / (2.0 * noiseStrength * noiseStrength + 1e-6));
float w = spatial * range;
accum += nc * w;
wsum += w;
}
}
vec3 denoised = accum / max(wsum, 1e-6);
vec3 detail = centerColor - denoised;
vec3 finalSharpened = centerColor + detail * sharpenStrength;
vec3 outRGB = finalSharpened;
if(int(viewMode)==0) outRGB = denoised;
else if(int(viewMode)==1) outRGB = centerColor;
float a = texture2DCv(inputImg.texture, uv).a * alpha;
gl_FragColor = vec4(clamp(outRGB, 0.0, 1.0), 1.0) * a;
}

void main() {
vec2 texelSize = 1.0 / inputImg.size;
vec2 center = vec2(cx,cy);
vec2 v = acScreenNorm.st - (vec4(center,0.0,1.0) * acLayerToScreen).xy;
float speed = length(strength / 2.0 / texelSize);
if(adaptive)
speed *= length( acLayerNorm.st - center );
else
speed *= smoothstep( 0.0, length(texelSize)*5.0, length( acLayerNorm.st - center ));
int nSamples = int(clamp(speed, 1.01, 100.01));
vec4 outColor = texture2DCv(inputImg.texture,acScreenNorm.st);
vec2 vnorm = normalize(v)*texelSize*speed;
for(int i=1; i<nSamples; i++ ) {
vec2 offset = vnorm * (float(i) / float(nSamples - 1) - 0.5);
outColor += texture2DCv(inputImg.texture, acScreenNorm.st-offset);
}
gl_FragColor = outColor/float(nSamples);
}

